
/* ================= RÉGLAGES : langue, thème, contenus sensibles ================= */
const PREFS = (()=>{ const d = {lang:null,theme:"auto",sens:"ask"}; try{ return Object.assign(d, JSON.parse(localStorage.getItem("sankofa-prefs")||"{}")); }catch(e){ return d; } })();
try{ document.documentElement.dataset.fs = PREFS.fs || "1"; }catch(e){}
function savePrefs(){ try{ localStorage.setItem("sankofa-prefs", JSON.stringify(PREFS)); }catch(e){} }
const LANG = PREFS.lang || (((navigator.languages&&navigator.languages[0])||navigator.language||"fr").toLowerCase().startsWith("fr") ? "fr" : "en");
const LOC = LANG==="en" ? "en-GB" : "fr-FR";
const EN = {};
window.__miss = [];
function t(s, v){
  let r = s;
  if(LANG==="en"){ if(EN[s]!=null) r = EN[s]; else if(!window.__miss.includes(s)) window.__miss.push(s); }
  if(v) r = r.replace(/\{(\w+)\}/g,(m,k)=>v[k]!=null ? v[k] : m);
  return r;
}
const decS = x => LANG==="en" ? String(x) : String(x).replace(".",",");
const plural = (n, one, many) => n>1 || n===0 && LANG==="en" ? many : one;

/* Thème : appliqué tout de suite pour éviter un éclair blanc. */
const darkMQ = matchMedia("(prefers-color-scheme: dark)");
function themeIsDark(){ return PREFS.theme==="dark" || (PREFS.theme==="auto" && darkMQ.matches); }
function applyTheme(){
  document.documentElement.dataset.theme = themeIsDark() ? "dark" : "light";
  document.documentElement.style.colorScheme = themeIsDark() ? "dark" : "light";
  const m = document.querySelector('meta[name="theme-color"]'); if(m) m.content = themeIsDark() ? "#0F1012" : "#F2F3EF";
  if(typeof readTheme==="function") readTheme();
}
applyTheme();
darkMQ.addEventListener?.("change", ()=>{ if(PREFS.theme==="auto") applyTheme(); });
document.documentElement.lang = LANG;

/* ================= DATES DES CHIFFRES ================= */
/* Y2025 = total de l'année ; M2026-01 = mois ; 2026-09-05 = au jour près. */
const VERIFIED = "2026-11-09";
const AT = {
  layers:{crime:VERIFIED, exil:"2025-12-31", hunger:"Y2025", enfants:"Y2025", slave:"Y2021", presse:"Y2025", apatride:"2025-12-31"},
  figs:{
    "180":["Y2025","M2026-01","Y2025","Y2026","M2025-02"],
    "275":["2026-09-05","2025-09-16","Y2025","Y2025","Y2025","M2026-04","2025-12-31"],
    "422":["M2026-03","M2026-07","M2026-07"],
    "760":["M2026-01","2025-12-31","M2026-02"],
    "729":["M2026-07","M2025-10","2025-12-31","M2025-09","Y2025"],
    "728":["M2026-04"],
    "887":["M2026-01","M2026-01","Y2025","M2026-01"],
    "332":["M2026-06","Y2025","M2024-09"],
    "104":["M2026-01","2025-12-31","Y2025"],
    "004":["M2025-07","2025-12-31","Y2021","Y2025"],
    "804":["M2023-03","Y2025"],
    "566":["Y2025"],"706":["Y2025"],"484":["Y2025"],"608":["Y2025"],
    "050":["2023-12-31"],"384":["2023-12-31"],"764":["2023-12-31"],
    "170":["2025-12-31"],"364":["M2026-06"],
    "408":["Y2021"],"232":["Y2021"],"478":["Y2021"],"682":["Y2021"],"792":["Y2021"],"762":["Y2021"],"784":["Y2021"],"643":["Y2021"],"414":["Y2021"]
  },
  live:["Y2025","M2026-03","Y2025","Y2025"],
  rhythms:["Y2025","Y2025","Y2025"],
  scale:{"180":"M2026-07","275":"M2026-04","422":"M2026-07","760":"M2026-01","887":"M2026-01","332":"M2026-06"}
};
function applyDates(){
  LAYERS.forEach(l=>l.at = AT.layers[l.id]);
  for(const id in AT.figs) AT.figs[id].forEach((a,j)=>{ if(C[id] && C[id].figs[j]) C[id].figs[j].at = a; });
  LIVE.forEach((r,i)=>r.at = AT.live[i]);
  RHYTHMS.forEach((r,i)=>r.at = AT.rhythms[i]);
  for(const id in AT.scale) if(DEEP[id] && DEEP[id].scale) DEEP[id].scale.at = AT.scale[id];
}
const MOIS_FR = ["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
const MOIS_EN = ["January","February","March","April","May","June","July","August","September","October","November","December"];
const MOIS_FR_S = ["janv.","févr.","mars","avr.","mai","juin","juil.","août","sept.","oct.","nov.","déc."];
const MOIS_EN_S = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
function atDate(a){ // fin de la période couverte
  if(a[0]==="Y") return new Date(+a.slice(1),11,31);
  if(a[0]==="M"){ const [y,m] = a.slice(1).split("-").map(Number); return new Date(y,m,0); }
  const [y,m,d] = a.split("-").map(Number); return new Date(y,m-1,d);
}
function fmtAt(a){
  const en = LANG==="en", MS = en?MOIS_EN_S:MOIS_FR_S;
  if(a[0]==="Y") return en ? `${a.slice(1)} figure` : `Chiffre de ${a.slice(1)}`;
  if(a[0]==="M"){ const [y,m] = a.slice(1).split("-").map(Number); return en ? `${MS[m-1]} ${y} figure` : `Chiffre de ${MS[m-1]} ${y}`; }
  const [y,m,d] = a.split("-").map(Number);
  return en ? `As of ${d} ${MS[m-1]} ${y}` : `Au ${d===1?"1er":d} ${MS[m-1]} ${y}`;
}
/* Ancienneté : un chiffre qui décrit une période finie depuis plus de 18 mois est signalé. */
function isOld(a){ const v = new Date(VERIFIED); return (v - atDate(a)) > 548*86400000; }
function asof(a, kind){
  if(!a) return "";
  const old = kind!=="event" && isOld(a);
  const tip = old ? t("Donnée ancienne : c'est la plus récente publiée par la source. Elle sera remplacée dès la prochaine édition.") : t("Date à laquelle ce chiffre s'applique. Vérifié le {d}.",{d:fmtDay(VERIFIED)});
  return `<span class="asof ${old?"old":""}" title="${esc(tip)}"><i></i>${esc(kind==="event"?fmtEvent(a):fmtAt(a))}${old?` · ${t("donnée ancienne")}`:""}</span>`;
}
function fmtEvent(a){
  const en = LANG==="en", MS = en?MOIS_EN_S:MOIS_FR_S;
  if(a[0]==="M"){ const [y,m] = a.slice(1).split("-").map(Number); return `${MS[m-1]} ${y}`; }
  if(a[0]==="Y") return a.slice(1);
  const [y,m,d] = a.split("-").map(Number); return en ? `${d} ${MS[m-1]} ${y}` : `${d===1?"1er":d} ${MS[m-1]} ${y}`;
}
function fmtDay(iso){ const [y,m,d] = iso.split("-").map(Number); return LANG==="en" ? `${d} ${MOIS_EN[m-1]} ${y}` : `${d===1?"1er":d} ${MOIS_FR[m-1]} ${y}`; }

