function applyDossiers(){
  for(const id in HARDQ){
    const H = HARDQ[id];
    H.fr.forEach((q,j)=>{ const e = H.en[j];
      Q[id].e.push(LANG==="en" ? {q:e[0],o:e[1],a:q[2],e:e[2]} : {q:q[0],o:q[1],a:q[2],e:q[3]}); });
  }
  for(const id in DOSSIERS){ const D = DOSSIERS[id]; if(D.en && D.en.check) D.en.check.a = D.fr.check.a;
    D.en.ch.forEach((c,i)=>{ c.s = D.fr.ch[i].s; c.hard = D.fr.ch[i].hard; }); }
  const ex = LEVELS[2]; ex.n = 5; ex.pass = 4; ex.desc = LANG==="en" ? "5 hard questions, 20 seconds each, based on the full dossier" : "5 questions difficiles, 20 secondes, tirées du dossier complet";
}
applyDossiers();

/* ================= v7 : thème, réglages, protection, juridique, jeu recadré ================= */
var APP_READY = false;
var TH = null;
function readTheme(){
  const cs = getComputedStyle(document.documentElement), g = k=>cs.getPropertyValue(k).trim();
  TH = {sea0:g("--g-sea0"),sea1:g("--g-sea1"),land:g("--g-land"),landLine:g("--g-landline"),grat:g("--g-grat"),halo:g("--g-halo"),halo0:g("--g-halo0"),shade:g("--g-shade"),dataLine:g("--g-dataline"),empty:g("--g-empty"),base:g("--g-base"),ink:g("--ink"),pill:g("--surface")};
  if(APP_READY){ grads = null; dirty = true; }
}

/* ---------- Globe et matrices aux couleurs du thème ---------- */
function makeGrads(){
  if(!TH) readTheme();
  const r = proj.scale(), [cx,cy] = proj.translate();
  const halo = gx.createRadialGradient(cx,cy,r*.95,cx,cy,r*1.12); halo.addColorStop(0,TH.halo); halo.addColorStop(1,TH.halo0);
  const sea = gx.createRadialGradient(cx-r*.35,cy-r*.4,r*.1,cx,cy,r); sea.addColorStop(0,TH.sea0); sea.addColorStop(1,TH.sea1);
  const sh = gx.createRadialGradient(cx-r*.3,cy-r*.35,r*.6,cx,cy,r*1.02); sh.addColorStop(0,"rgba(0,0,0,0)"); sh.addColorStop(1,TH.shade);
  grads = {halo,sea,sh,r,cx,cy};
}
function fillFor(id){
  const c = C[id]; if(!c) return null;
  const lv = c.layers[active]; if(!lv) return null;
  return d3.interpolateRgb(TH.base, L(active).hex)(routesOn ? .12+lv*.07 : .35+lv*.2);
}
function gDraw(now){
  if(!grads) makeGrads();
  const {r,cx,cy} = grads;
  gx.clearRect(0,0,GW,GW);
  if(zk<1.6){ gx.fillStyle = grads.halo; gx.beginPath(); gx.arc(cx,cy,r*1.12,0,6.283); gx.fill(); }
  gx.beginPath(); gpath(sphere); gx.fillStyle = grads.sea; gx.fill();
  if(!moving){ gx.beginPath(); gpath(grat); gx.strokeStyle = TH.grat; gx.lineWidth = .6; gx.stroke(); }
  const baseF = (zk>=1.9 && !moving && !anim) ? F50 : F110;
  gx.beginPath(); for(const f of baseF) gpath(f);
  gx.fillStyle = TH.land; gx.fill(); gx.strokeStyle = TH.landLine; gx.lineWidth = .5; gx.stroke();
  for(const f of DATA_F){
    const col = fillFor(f.id); if(!col) continue;
    gx.beginPath(); gpath(f); gx.fillStyle = col; gx.fill();
    gx.strokeStyle = hover===f.id ? TH.ink : TH.dataLine; gx.lineWidth = hover===f.id?1.4:.6; gx.stroke();
  }
  gx.beginPath(); gpath(sphere); gx.fillStyle = grads.sh; gx.fill();
  const center = [-rot[0],-rot[1]], hex = L(active).hex, k = ((now||0)%1800)/1800;
  for(const id in C){
    if(!C[id].layers[active] || !featById[id]) continue;
    const c = centroid(id); if(d3.geoDistance(c,center)>1.5) continue;
    const p = proj(c); if(!p) continue;
    gx.beginPath(); gx.arc(p[0],p[1],3,0,6.283); gx.fillStyle = hex; gx.fill();
    if(!moving){ gx.beginPath(); gx.arc(p[0],p[1],3+k*12,0,6.283); gx.strokeStyle = hex; gx.globalAlpha = (1-k)*.7; gx.lineWidth = 1.2; gx.stroke(); gx.globalAlpha = 1; }
  }
  for(let i=ripples.length-1;i>=0;i--){
    const rp = ripples[i], age = (now-rp.t)/1600;
    if(age>1){ ripples.splice(i,1); continue; }
    const c = centroid(rp.id); if(d3.geoDistance(c,center)>1.5) continue;
    const p = proj(c); if(!p) continue;
    gx.beginPath(); gx.arc(p[0],p[1],4+age*26,0,6.283);
    gx.strokeStyle = "#7A55F5"; gx.globalAlpha = (1-age)*.9; gx.lineWidth = 2; gx.stroke(); gx.globalAlpha = 1;
  }
  drawFocus(now, center);
  if(routesOn) drawRoutes(now, center);
  dirty = false; lastDraw = now;
}
function matrix(canvas,count,color,cols){
  const w = canvas.parentElement.clientWidth || 300;
  cols = cols || Math.max(14, Math.floor(w/11));
  const gap = w/cols, rows = Math.ceil(count/cols), h = rows*gap;
  canvas.width = w*DPR; canvas.height = h*DPR; canvas.style.height = h+"px";
  const ctx = canvas.getContext("2d"); ctx.setTransform(DPR,0,0,DPR,0,0);
  const start = performance.now(), dur = reduce?0:1400, empty = TH.empty;
  function draw(now){
    const k = dur? Math.min(1,(now-start)/dur):1, shown = Math.floor(count*d3.easeCubicOut(k));
    ctx.clearRect(0,0,w,h);
    for(let i=0;i<count;i++){
      const x=(i%cols)*gap+gap/2, y=Math.floor(i/cols)*gap+gap/2;
      ctx.beginPath(); ctx.arc(x,y,gap*0.32,0,6.283);
      ctx.fillStyle = i<shown?color:empty; ctx.fill();
    }
    if(k<1) requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
}
function updateZoomUI(){ const el=$("#zoomLvl"); if(el) el.textContent = "×"+decS(zk.toFixed(1)); }

/* ---------- Visite guidée ---------- */
function tourShow(){
  const s = TOUR[tourI]; setLayer(s.layer); const zz = zk>1.3; if(zz) zoomTo(1,300); setTimeout(()=>{ flyTo(s.id,{zoom:Math.min(s.k||2.4,5)}); focusC = {id:s.id, t:performance.now()}; }, zz?320:0);
  const cap = $("#tourCap");
  cap.innerHTML = `<button class="tnav" id="tPrev" aria-label="${t("Escale précédente")}" ${tourI?"":"disabled"}>‹</button>
    <div class="tbody"><span class="tstep" style="color:${L(s.layer).hex}">${tourI+1}/${TOUR.length} · ${esc(s.t)}</span><span class="ttext">${esc(s.x)}</span></div>
    <button class="tnav" id="tNext" aria-label="${t("Escale suivante")}">${tourI+1<TOUR.length?"›":"✓"}</button>
    <button class="tnav ghost" id="tOpen" aria-label="${t("Ouvrir la fiche")}">↗</button>
    <button class="tnav ghost" id="tQuit" aria-label="${t("Quitter la visite")}">×</button>`;
  cap.classList.add("show");
  $("#tNext").onclick=tourNext; $("#tQuit").onclick=tourEnd;
  $("#tPrev").onclick=()=>{ if(tourI){ tourI--; tourShow(); } };
  $("#tOpen").onclick=()=>{ const id=s.id; tourEnd(); location.hash="pays-"+C[id].slug; };
}
function tourNext(){ if(tourI+1>=TOUR.length){ state.tour=true; save(); tourEnd(); toast(t("Visite terminée")); return; } tourI++; tourShow(); }

/* ---------- Lectures ---------- */
function renderLayerCard(){
  if(routesOn) return renderRoutesLegend();
  const l = L(active), el = $("#layerCard"); el.classList.remove("rlpanel");
  el.style.setProperty("--lc", l.hex);
  const list = Object.values(C).filter(c=>c.layers[active]).sort((a,b)=>b.layers[active]-a.layers[active]);
  el.innerHTML = `<span class="lname term" tabindex="0" data-t="${LAYER_TERM[l.id]}">${l.name}</span><div class="big">${l.big}</div><p>${gl(l.text,2)}</p>
    ${asof(l.at)}
    ${l.mx?`<div class="mxlegend"><i></i>${l.unit}</div><canvas class="matrix" id="mx"></canvas>`:""}
    <div class="chips">${list.map(c=>`<button class="chip" data-id="${c.id}">${esc(c.short)}</button>`).join("")}</div>
    ${srcd(l.src)}`;
  if(l.mx) matrix($("#mx"), l.mx, l.hex, l.mx>150?30:20);
  el.querySelectorAll(".chip").forEach(b=>{
    b.onmouseenter=()=>flyTo(b.dataset.id);
    b.onclick=()=>location.hash="pays-"+C[b.dataset.id].slug;
  });
}
function renderRhythms(){
  $("#rhythms").innerHTML = RHYTHMS.map(r=>`<div class="rh" style="--c:${r.c}"><b>${r.n}</b><span>${esc(r.d)}</span>${asof(r.at)}${srcd([r.s])}</div>`).join("");
}

/* ---------- Cartes pays et explorer ---------- */
function pcard(id){
  const c = C[id], st = state.stamps[id], main = mainLayer(c);
  return `<button class="card pcard" data-id="${id}" style="--tint:color-mix(in srgb,${main.hex} 8%,var(--surface2))">
    <div class="art"><canvas data-sil="${id}" data-col="${main.hex}"></canvas>${st?`<span class="stamp" style="color:${RARITY[st.r].col}">${RARITY[st.r].name}</span>`:""}</div>
    <div class="meta"><b>${esc(c.short)}</b><span>${esc(c.region)}</span><div class="dots">${dotsFor(c)}</div></div></button>`;
}
function renderExplorer(){
  $("#filters").innerHTML = [`<button class="filter" data-f="all" aria-pressed="${exFilter==="all"}">${t("Tous")}</button>`]
    .concat(LAYERS.map(l=>`<button class="filter" data-f="${l.id}" aria-pressed="${exFilter===l.id}"><span class="chipdot" style="--c:${l.hex}"></span>${l.name}</button>`)).join("");
  document.querySelectorAll(".filter").forEach(b=>b.onclick=()=>{exFilter=b.dataset.f;renderExplorer();});
  const ids = Object.keys(C).filter(id=>exFilter==="all"||C[id].layers[exFilter])
    .sort((a,b)=>(FEATURED.includes(b)-FEATURED.includes(a)) || C[a].short.localeCompare(C[b].short,LANG));
  $("#exGrid").innerHTML = ids.map(pcard).join("");
  hydrate($("#exGrid"));
}

/* ---------- Fiche pays ---------- */
const GHOST = id=>`<div class="stampwrap ghost"><svg viewBox="0 0 200 200"><circle class="gring" cx="100" cy="100" r="94" fill="none" stroke-width="2" stroke-dasharray="6 6"/><path class="gfill" d="${svgPath(id,[[62,58],[138,126]])}"/></svg></div>`;
function scaleHTML(sc,hex){
  return `<div class="card scale"><div class="eyebrow">${t("À l'échelle d'une classe")}</div>
    <p class="scl">${t("Si ta classe de 30 élèves vivait ici, {n} d'entre eux {x}.",{n:`<b style="color:${hex}">${sc.n}</b>`,x:esc(sc.t)})}</p>
    <div class="ppl">${Array.from({length:30},(_,i)=>`<i class="${i<sc.n?"on":""}" style="--c:${hex};--d:${i*40}ms"></i>`).join("")}</div>
    <div class="scn">${esc(sc.note)}</div>${asof(sc.at)}${srcd([sc.s])}</div>`;
}
function areaVsFrance(id){
  const r = d3.geoArea(featById[id])/FR_AREA;
  if(r>=1.15) return t("{x} fois la France",{x:decS(r.toFixed(1))});
  if(r>0.87) return t("À peu près la France");
  return t("{x} fois plus petit que la France",{x:Math.round(1/r)});
}
/* Pays dont la fiche décrit des violences de masse, et passages les plus durs. */
const HARD = {"180":[],"275":[2],"729":[2],"104":[1],"004":[],"804":[],"566":[],"706":[]};
const isHardFig = f => f.l==="crime" || f.l==="enfants";
let gateOk = {};
function softBlock(html){
  return `<div class="softwrap"><div class="softin">${html}</div><button class="softbtn" type="button"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>${t("Passage sensible · Afficher")}</button></div>`;
}
function helpHTML(){
  if(LANG==="en") return `<div class="card help"><div class="hico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9z"/></svg></div><div>
    <b>Feeling heavy?</b><p>It is normal to be shaken by what you read. Take a break, and talk about it with someone you trust. If you need to talk, <a href="https://findahelpline.com" target="_blank" rel="noopener">Find A Helpline</a> lists free, confidential helplines in your country. In France, Fil Santé Jeunes listens every day from 9am to 11pm: <a href="tel:0800235236">0 800 235 236</a>.</p></div></div>`;
  return `<div class="card help"><div class="hico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 21s-7-4.5-9.5-9A5.5 5.5 0 0 1 12 6a5.5 5.5 0 0 1 9.5 6c-2.5 4.5-9.5 9-9.5 9z"/></svg></div><div>
    <b>Ça te pèse ?</b><p>C'est normal d'être secoué par ce que tu lis. Fais une pause, parles-en à quelqu'un de confiance. Fil Santé Jeunes t'écoute gratuitement et anonymement, tous les jours de 9 h à 23 h : <a href="tel:0800235236">0 800 235 236</a> ou par chat sur <a href="https://www.filsantejeunes.com" target="_blank" rel="noopener">filsantejeunes.com</a>. Si tu vas vraiment mal, le <a href="tel:3114">3114</a> répond jour et nuit.</p></div></div>`;
}
function renderPays(id){
  const c = C[id], D = DEEP[id]; visit(id);
  const main = mainLayer(c), hard = id in HARD;
  const mode = hard ? (gateOk[id] || (PREFS.sens==="ask" ? "gate" : PREFS.sens)) : "show";
  const soft = mode==="soft" || mode==="gate";
  const figs = c.figs.map(f=>{
    const l = L(f.l);
    const inner = `${f.n?`<div class="n">${esc(f.n)}</div><div class="d">${gl(f.d,2)}</div>`:`<p class="t">${gl(f.t,3)}</p>`}`;
    return `<div class="card fig" style="--c:${l.hex}">
      <div class="lab"><i></i><span class="eyebrow">${f.lab?t(f.lab):l.name}</span></div>
      ${soft && hard && isHardFig(f) ? softBlock(inner) : inner}
      ${f.beat?`<div class="rate"><span class="beat" style="--c:${l.hex}" data-beat="${f.beat}"></span>${t("Ce point bat au rythme réel : une fois toutes les {s} secondes.",{s:decS(f.beat)})}</div>`:""}
      ${f.people && f.people>=1?`<div class="mxlegend" style="--lc:${l.hex}"><i></i>${t("1 point = 100 000 personnes")}</div><canvas data-mx="${Math.round(f.people*10)}" data-col="${l.hex}"></canvas>`:""}
      <div class="figfoot">${asof(f.at, f.t?"event":"")}${srcd(f.s2?[f.s,f.s2]:[f.s])}</div></div>`;
  }).join("");
  const hist = c.hist.length?`<div class="sect"><div class="secthead"><div><div class="eyebrow">${t("Histoire")}</div><h2>${t("Les dates qui ont façonné {x}.",{x:esc(c.de||c.short)})}</h2></div></div>
    <div class="timeline">${c.hist.map(h=>`<div class="card ev"><div class="y">${h[0]}</div><p>${esc(h[1])}</p></div>`).join("")}</div></div>`:"";
  const hardP = HARD[id]||[];
  const deep = D?`<div class="sect"><div class="secthead"><div><div class="eyebrow">${t("Comprendre")}</div><h2>${t("L'essentiel en trois minutes.")}</h2></div></div>
      <div class="understand"><div class="card prose">${D.txt.map((p,i)=>soft && hardP.includes(i) ? softBlock(`<p>${gl(p,3)}</p>`) : `<p>${gl(p,3)}</p>`).join("")}</div>
      <div class="side">${D.scale?scaleHTML(D.scale,main.hex):""}
        <div class="card know"><div class="eyebrow">${t("Le savais-tu ?")}</div><p>${esc(D.sav)}</p></div>
        <div class="card figure"><div class="eyebrow">${t("Une figure")}</div><b>${esc(D.fig.n)}</b><span class="fd">${esc(D.fig.d)}</span><p>${esc(D.fig.t)}</p></div>
      </div></div></div>`:"";
  const st = state.stamps[id], r = st?.r||0;
  const parcours = c.quiz?`<div class="sect"><div class="card parcours">
      <div class="pinfo"><div class="eyebrow">${t("Parcours")}</div><h2>${t("Teste ce que tu as appris.")}</h2>
        <p>${hasM(id)?t("Cinq niveaux, de la Découverte au niveau Maître. Les questions s'ouvrent sur un écran à part, sans la fiche sous les yeux."):t("Quatre niveaux, de la Découverte au Défi légendaire. Les questions s'ouvrent sur un écran à part, sans la fiche sous les yeux.")}</p>
        <div class="pips big">${rList(id).map(k=>`<span class="pip ${r>=k?"on":""}" style="--c:${RARITY[k].col}">${RARITY[k].name}</span>`).join("")}</div>
        <a class="cta" href="#quiz-${c.slug}">${r?t("Continuer le parcours"):t("Commencer le parcours")}</a></div>
      <div class="pstamp">${st?stampSVG(id,st.r,st.d):GHOST(id)}</div>
    </div></div>`:"";
  $("#paysIn").innerHTML = `
    <div class="phero">
      <div>
        <button class="back" id="backBtn">← ${t("Retour")}</button>
        <div class="eyebrow" style="margin-top:18px">${esc(c.region)}</div>
        <h1>${esc(c.name)}</h1>
        <div class="tags">${LAYERS.filter(l=>c.layers[l.id]).map(l=>`<span class="tag term" tabindex="0" data-t="${LAYER_TERM[l.id]}" style="--c:${l.hex}"><i></i>${l.name}</span>`).join("")}</div>
        ${updOf(id)?`<p class="cupd"><i></i>${t("Mise à jour : {d}",{d:updOf(id)})}</p>`:""}
        <p class="resume">${gl(c.resume,3)}</p>
        ${DOSSIERS[id]?`<a class="dlink" href="#dossier-${c.slug}"><span class="dli">${ico("doc")}</span><span><b>${t("Lire le dossier complet")}</b><em>${t("{n} chapitres",{n:dossierOf(id).ch.length})} · ${t("{n} min de lecture",{n:readMin(dossierOf(id))})}</em></span><span class="dla">→</span></a>`:""}
        <a class="dlink qlink" href="#quiz-${c.slug}"><span class="dli">${ico("check")}</span><span><b>${state.stamps[id]?t("Continuer le parcours"):t("Faire le quiz")}</b><em>${state.stamps[id]?t("Tampon {r} obtenu",{r:RARITY[state.stamps[id].r].name}):t("{n} niveaux · un tampon à gagner",{n:(typeof topLv==="function"?topLv(id):3)+1})}</em></span><span class="dla">→</span></a>
        ${D?`<div class="reperes">${D.rep.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join("")}<div><span>${id==="104"?t("Superficie du Myanmar"):t("Superficie")}</span><b>${areaVsFrance(id)}</b></div></div>`:""}
        <div class="pact"><button class="cta ghost" id="goGlobe">${t("Voir sur le globe")}</button><button class="cta ghost" id="shareImg">${t("Partager en image")}</button><button class="cta ghost" id="share">${t("Copier le lien")}</button></div>
      </div>
      <div class="part"><canvas id="bigSil"></canvas><button class="locator" id="locator" type="button" aria-label="${esc(t("Voir sur le globe"))}"><canvas id="locCv"></canvas><span>${t("{x} sur le globe",{x:esc(c.short)})}</span></button></div>
    </div>
    ${hard && mode!=="gate" ? `<div class="sensnote"><span>${mode==="soft"?t("Les passages les plus durs sont masqués."):t("Cette fiche décrit des violences de masse.")}</span><button class="linkbtn" id="sensToggle">${mode==="soft"?t("Tout afficher"):t("Masquer les passages durs")}</button></div>`:""}
    <div class="sect"><div class="secthead"><div><div class="eyebrow">${t("Les chiffres")}</div><h2>${t("Ce que vivent ses habitants.")}</h2></div></div><div class="figs">${figs}</div></div>
    ${deep}
    ${DOSSIERS[id]?`<div class="sect">${dossierTeaser(id)}</div>`:""}
    ${hist}
    ${hard?`<div class="sect">${helpHTML()}</div>`:""}
    ${parcours}
    <p class="src" style="margin-top:28px">${t("Chiffres vérifiés le {d}. Chaque chiffre indique la date à laquelle il s'applique.",{d:fmtDay(VERIFIED)})}</p>`;
  $("#backBtn").onclick=()=>history.length>1?history.back():location.hash="globe";
  $("#goGlobe").onclick=()=>{ location.hash="globe"; setTimeout(()=>focusCountry(id),380); };
  const lc=$("#locator"); if(lc) lc.onclick=()=>$("#goGlobe").click();
  $("#share").onclick=()=>{ const u="https://sankofa-atlas.org/"+c.slug+"/"; (navigator.clipboard?navigator.clipboard.writeText(u):Promise.reject()).then(()=>toast(t("Lien copié"))).catch(()=>toast(u)); };
  $("#shareImg").onclick=()=>shareCard("fig",id);
  $("#paysIn").querySelectorAll(".softbtn").forEach(b=>b.onclick=()=>b.parentElement.classList.add("open"));
  const tg=$("#sensToggle"); if(tg) tg.onclick=()=>{ gateOk[id] = mode==="soft" ? "show" : "soft"; const y=scrollY; renderPays(id); scrollTo({top:y,behavior:"instant"}); };
  if(mode==="gate") showGate(id);
  requestAnimationFrame(()=>{
    countUp($("#paysIn"));
    silhouette($("#bigSil"),id,main.hex,{animate:true,pad:.08}); drawLocator(id);
    document.querySelectorAll("#paysIn canvas[data-mx]").forEach(cv=>matrix(cv,+cv.dataset.mx,cv.dataset.col));
  });
}
function showGate(id){
  const c = C[id], m = $("#modal");
  m.innerHTML = `<div class="mbox gate" role="dialog" aria-modal="true" aria-labelledby="gT">
    <div class="eyebrow">${t("Avant de lire")}</div><h2 id="gT">${t("Cette fiche parle de violences de masse.")}</h2>
    <p>${t("{x} : massacres, famines, violences contre des enfants. Les faits sont décrits sans images choquantes, avec leurs sources. Tu peux tout lire, ou masquer les passages les plus durs et les ouvrir un par un.",{x:esc(c.name)})}</p>
    <div class="gatebtns"><button class="cta" data-m="show">${t("Tout afficher")}</button><button class="cta ghost" data-m="soft">${t("Masquer les passages durs")}</button><button class="cta ghost" data-m="back">${t("Revenir")}</button></div>
    <label class="remember"><input type="checkbox" id="gRem"> ${t("Retenir mon choix pour toutes les fiches")}</label>
    ${helpHTML()}</div>`;
  m.classList.add("show");
  m.querySelectorAll("[data-m]").forEach(b=>b.onclick=()=>{
    const v = b.dataset.m; m.classList.remove("show");
    if(v==="back"){ history.length>1?history.back():location.hash="globe"; return; }
    if($("#gRem").checked){ PREFS.sens = v; savePrefs(); }
    gateOk[id] = v; renderPays(id);
  });
}

/* ---------- Parcours ---------- */
function renderQuizView(id){
  const qb0 = document.getElementById("quizBox");
  if(QUIZ_LIVE===id && qb0 && qb0.isConnected && qb0._run && qb0.querySelector(".opts")) return;
  const c = C[id], main = mainLayer(c);
  $("#quizIn").innerHTML = `<div class="qhead">
      <a class="back" href="#pays-${c.slug}">← ${t("Revoir la fiche")}</a>
      <div class="qtitle"><canvas id="qSil"></canvas><div><div class="eyebrow">${t("Parcours")}</div><h1>${esc(c.short)}</h1></div></div>
    </div>
    <div class="lvls" id="lvls"></div><div class="card quiz" id="quizBox"></div>`;
  requestAnimationFrame(()=>silhouette($("#qSil"),id,main.hex,{pad:.08,step:4}));
  const r = state.stamps[id]?.r||0;
  renderLevels(id, Math.min(topLv(id), r));
}
function renderLevels(id,sel){
  const r = state.stamps[id]?.r || 0;
  $("#lvls").innerHTML = LEVELS.slice(0, topLv(id)+1).map((lv,i)=>{
    const open = i===0 || r>=i, rr = RARITY[i+1];
    return `<button class="lvl ${i===3?"legend":""}${i===4?" master":""}" data-i="${i}" aria-pressed="${i===sel}" ${open?"":"disabled"}>
      <span class="lvn">${open?"":LOCK}${lv.name}${r>=i+1?` <span class="done">✓</span>`:""}</span>
      <span class="lvr" style="color:${rr.col}">${t("Tampon {r}",{r:rr.name})}</span>
      <span class="lvx">${lv.desc} · ${lv.xp} XP</span></button>`;
  }).join("");
  document.querySelectorAll(".lvl").forEach(b=>b.onclick=()=>{ if(!b.disabled) renderLevels(id,+b.dataset.i); });
  const Q4 = C[id].quiz, lv = LEVELS[sel];
  const pool = sel===3 ? Q4.d.concat(Q4.i,Q4.e) : Q4[lv.k];
  runQuiz($("#quizBox"), d3.shuffle(pool.slice()).slice(0,lv.n), {id, lv:sel});
}
var QUIZ_LIVE = null;
addEventListener("hashchange", ()=>{ if(QUIZ_LIVE && C[QUIZ_LIVE] && location.hash!=="#quiz-"+C[QUIZ_LIVE].slug){ const qb = document.getElementById("quizBox"); if(qb) qb._run = null; QUIZ_LIVE = null; } });
function runQuiz(box, qs0, opt={}){
  const qs = qs0.map(shuffleQ);
  let i = 0, score = 0, timer = null, done = false, shownAt = 0;
  const run = box._run = {}, alive = ()=> box._run===run && box.isConnected;
  if(opt.id && opt.lv!=null) QUIZ_LIVE = opt.id;
  const lv = opt.lv ?? -1, LV = LEVELS[lv], timed = LV && LV.time;
  function show(){
    clearInterval(timer);
    if(!alive()) return;
    done = false;
    if(i>=qs.length) return end();
    const q = qs[i];
    box.innerHTML = `<div class="qprog">${qs.map((_,k)=>`<i class="${k<i?"done":""}"></i>`).join("")}</div>
      <div class="qtop"><span class="eyebrow">${LV?LV.name+" · ":""}${t("Question {a} sur {b}",{a:i+1,b:qs.length})}</span>${timed?`<span class="qtime" id="qt">${LV.time}</span>`:""}</div>
      ${timed?`<div class="tbar"><i id="tb"></i></div>`:""}
      <h3>${esc(q.q)}</h3>
      <div class="opts">${q.o.map((o,k)=>`<button class="opt" data-k="${k}"><span class="ok-l">${"ABCD"[k]}</span>${esc(o)}</button>`).join("")}</div>
      <div class="explain" id="exp"></div><div class="qfoot"></div>`;
    shownAt = performance.now();
    box.querySelectorAll(".opt").forEach(b=>b.onclick=()=>{ if(performance.now()-shownAt<450) return; answer(+b.dataset.k); });
    if(timed){
      const t0 = performance.now(), T = LV.time*1000;
      timer = setInterval(()=>{
        if(!alive() || done){ clearInterval(timer); return; }
        const left = Math.max(0,T-(performance.now()-t0));
        const qt = box.querySelector("#qt"), tb = box.querySelector("#tb");
        if(qt) qt.textContent = Math.ceil(left/1000); if(tb) tb.style.width = (left/T*100)+"%";
        if(left<=0){ clearInterval(timer); answer(-1); }
      },100);
    }
  }
  function answer(k){
    clearInterval(timer);
    if(done || !alive()) return;
    done = true;
    const q = qs[i], ok = k===q.a; if(ok) score++;
    box.querySelectorAll(".opt").forEach(x=>{x.disabled=true; if(+x.dataset.k===q.a) x.classList.add("ok"); if(+x.dataset.k===k && !ok) x.classList.add("ko");});
    const e = box.querySelector("#exp");
    e.innerHTML = `<b>${ok?t("Exact."):k===-1?t("Temps écoulé."):t("Pas tout à fait.")}</b> ${esc(q.e)}`; e.classList.add("show");
    const last = i+1>=qs.length, fail = LV && lv===3 && !ok;
    box.querySelector(".qfoot").innerHTML = `<button class="cta">${fail?t("Voir le résultat"):last?t("Voir mon résultat"):t("Question suivante")}</button>`;
    let went = false;
    box.querySelector(".qfoot .cta").onclick=()=>{ if(went || !alive()) return; went = true; if(fail){ i=qs.length; } else i++; show(); };
    box.querySelector(".qfoot .cta").focus({preventScroll:true});
  }
  function end(){
    if(!alive()) return;
    if(opt.id && opt.lv!=null && QUIZ_LIVE===opt.id) QUIZ_LIVE = null;
    const wonLv = !!(opt.id && LV && score>=LV.pass);
    const lvBefore = levelInfo().l;
    const already = !!(opt.id && LV && (state.stamps[opt.id]?.r||0) >= lv+1);
    const gained = xpFor(opt, score, wonLv); state.xp += gained;
    let msg = "", newR = 0;
    if(opt.id && LV){
      const won = score>=LV.pass; newR = won ? lv+1 : 0;
      const prev = state.stamps[opt.id]?.r || 0;
      if(newR>prev){ state.stamps[opt.id] = {r:newR,d:new Date().toLocaleDateString(LOC)}; queueCelebration({stamp:opt.id}); }
      msg = newR>prev ? t("Tampon {r} obtenu.",{r:RARITY[newR].name}) : won ? t("Niveau réussi. Ton meilleur tampon est conservé.") : lv===3 ? t("Le Défi légendaire n'admet aucune erreur. Les questions changent à chaque essai.") : t("Il faut {p} bonnes réponses sur {n}. Les questions changent à chaque essai.",{p:LV.pass,n:LV.n});
      if(newR>prev && newR===2) msg += " "+t("Le niveau Expert est débloqué.");
      if(newR>prev && newR===4 && hasM(opt.id)) msg += " "+t("Le niveau Maître est débloqué.");
      if(newR>prev && newR===3) msg += " "+t("Le Défi légendaire est débloqué.");
      if(won){ learned("country", opt.id); bump("lvl"); if(lv===0) bump("disc", opt.id); if(lv>=2) bump("expert"); }
    }
    if(opt.daily){
      const today = new Date().toDateString(), y = new Date(Date.now()-86400000).toDateString();
      if(state.lastDaily!==today){ state.streak = state.lastDaily===y ? state.streak+1 : 1; state.lastDaily = today; state.dailyLog = (state.dailyLog||[]).concat(today).slice(-30); bump("daily"); }
      msg = state.streak>1 ? t("Série : {n} jours d'affilée. Reviens demain.",{n:state.streak}) : t("Série : 1 jour. Reviens demain pour la prolonger.");
    }
    if(opt.notion!=null){
      state.notions = state.notions||[];
      if(score===1 && !state.notions.includes(opt.notion)){ state.notions.push(opt.notion); learned("notion", opt.notion); bump("notion"); }
      msg = score===1 ? t("Notion validée.") : t("Relis la leçon et réessaie.");
    }
    if(opt.id && LV && window.skfEvent) skfEvent("quiz", C[opt.id].slug+":"+lv+":"+(score>=LV.pass?1:0));
    if(opt.id && LV){ const rr = state.stamps[opt.id]?.r || 0; state.resumeQ = rr>=topLv(opt.id)+1 ? null : {id:opt.id, lv:Math.min(topLv(opt.id),rr), d:Date.now()}; }
    save();
    const up = levelInfo().l>lvBefore; if(up) queueCelebration({level:levelInfo().l});
    box.innerHTML = `<div class="result">
      ${newR&&opt.id?`<div class="reveal soft">${stampSVG(opt.id,newR,state.stamps[opt.id].d)}</div>`:`<div class="score">${score}/${qs.length}</div>`}
      <p><b>${esc(msg)}</b></p>${gained?`<p class="xpgain">+${gained} XP${already&&wonLv?" · "+t("niveau déjà réussi"):""}</p>`:""}
      ${(up||newR) && !opt.notion ? `<p class="passnote">${t("Ta progression t'attend dans ton passeport.")}</p>`:""}
      <div class="pact" style="justify-content:center">${opt.id?`<button class="cta ghost" id="again">${t("Rejouer")}</button>`:""}${(opt.notion!=null||opt.dossier)&&score<1?`<button class="cta ghost" id="again">${t("Réessayer")}</button>`:""}${opt.id&&LV?`<button class="cta ghost" id="shareRes">${t("Partager mon résultat")}</button>`:""}${opt.id||opt.daily?`<a class="cta" href="#passeport">${t("Mon passeport")}</a>`:""}</div></div>`;
    const a = box.querySelector("#again");
    const shr = box.querySelector("#shareRes"); if(shr) shr.onclick=()=>shareCard("result", opt.id, {score, n:qs.length, lv, won:score>=LV.pass});
    if(a) a.onclick=()=>{ if(opt.id) renderLevels(opt.id, Math.min(topLv(opt.id),(state.stamps[opt.id]?.r||0))); else { i=0; score=0; show(); } };
    if(opt.onEnd) opt.onEnd(score);
  }
  show();
}
function stampSVG(id,r,date,small){
  const c = C[id], R = RARITY[r], uid = "s"+id+r+(small?"m":"")+Math.random().toString(36).slice(2,6);
  const p = svgPath(id,[[62,58],[138,126]]);
  return `<div class="stampwrap r${r} ${small?"small":""}" title="${esc(t("Tampon {r}",{r:R.name}))}">
  <svg viewBox="0 0 200 200" role="img" aria-label="${esc(t("Tampon {r}",{r:R.name}))} · ${esc(c.short)}">
    <defs><path id="${uid}" d="M100,100 m-78,0 a78,78 0 1,1 156,0 a78,78 0 1,1 -156,0"/></defs>
    <circle cx="100" cy="100" r="94" fill="${R.col}" fill-opacity=".06" stroke="${R.col}" stroke-width="3"/>
    <circle cx="100" cy="100" r="66" fill="none" stroke="${R.col}" stroke-width="1.2" stroke-dasharray="3 4"/>
    <text font-family="Geist Mono, monospace" font-size="11.5" letter-spacing="2.6" fill="${R.col}"><textPath href="#${uid}">SANKOFA · ${esc(c.short.toUpperCase())} · ${esc(R.name.toUpperCase())} · </textPath></text>
    <path d="${p}" fill="${R.col}" fill-opacity=".85"/>
    <text x="100" y="146" text-anchor="middle" font-family="Geist Mono, monospace" font-size="10" fill="${R.col}">${esc(date||"")}</text>
    ${r>=3?`<g fill="${R.col}">${[0,1,2,3].slice(0,r-1).map(k=>`<circle cx="${94-((r-2)*6)+k*12}" cy="44" r="2.6"/>`).join("")}</g>`:""}
  </svg></div>`;
}

/* ---------- Progression : célébrations gardées pour le passeport ---------- */
function queueCelebration(x){
  const c = state.cele = state.cele || {level:0,stamps:[],badges:[]};
  if(x.level) c.level = Math.max(c.level||0, x.level);
  if(x.stamp && !c.stamps.includes(x.stamp)) c.stamps.push(x.stamp);
  if(x.badge && !c.badges.includes(x.badge)) c.badges.push(x.badge);
  store.set(state); markPass();
}
function hasCele(){ const c = state.cele; return !!(c && (c.level || c.stamps.length || c.badges.length)); }
function markPass(){ const on = hasCele(); document.querySelectorAll('[data-v="passeport"]').forEach(a=>a.classList.toggle("hasnew",on)); }
function celebrate(){
  if(!hasCele()) return;
  const c = state.cele, el = $("#lvlup"); if(!el) return;
  const ids = c.stamps.filter(id=>state.stamps[id] && C[id]);
  const badges = c.badges.map(b=>BADGES.find(x=>x.id===b)).filter(Boolean);
  const lvTitle = c.level ? TITLES[Math.min(TITLES.length-1,c.level-1)] : "";
  const head = ids.length > 1 ? t("{n} nouveaux tampons",{n:ids.length}) : ids.length === 1 ? t("Nouveau tampon") : c.level ? t("Nouveau niveau") : t("Nouveau badge");
  const shown = ids.slice(0,3);
  const stamps = shown.length ? `<div class="nvrow n${shown.length}">${shown.map((id,i)=>{ const st = state.stamps[id];
      return `<div class="nvstamp" style="--i:${i}"><div class="nvpress"><span class="nvring"></span>${stampSVG(id,st.r,st.d)}</div><b>${esc(C[id].short)}</b><span>${t("Tampon {r}",{r:RARITY[st.r].name})}</span></div>`; }).join("")}</div>${ids.length>3?`<p class="nvmore">${t("et {n} de plus",{n:ids.length-3})}</p>`:""}` : "";
  const level = c.level ? (ids.length ? `<p class="nvlevel"><i></i>${t("Niveau {n}",{n:c.level})} · ${esc(lvTitle)}</p>` : `<b class="nvbig">${c.level}</b><span class="nvtitle">${esc(lvTitle)}</span>`) : "";
  const bd = badges.length ? `<p class="nvbadges">${badges.map(B=>`<span>${t("Badge")} · ${esc(t(B.n))}</span>`).join("")}</p>` : "";
  el.innerHTML = `<div class="lvcard nvcard" role="dialog" aria-modal="true" aria-label="${esc(head)}"><div class="eyebrow">${head}</div>${stamps}${level}${bd}<div class="nvacts">${ids.length?`<button class="cta ghost" id="lvShare">${t("Partager mon tampon")}</button>`:""}<button class="cta" id="lvOk">${t("Continuer")}</button></div></div>`;
  el.classList.add("show");
  const close = ()=>el.classList.remove("show");
  $("#lvOk").onclick = close; el.onclick = e=>{ if(e.target === el) close(); };
  const lsh = $("#lvShare"); if(lsh) lsh.onclick = ()=>{ close(); shareCard("stamp", ids[0]); };
  state.cele = {level:0,stamps:[],badges:[]}; store.set(state); markPass();
}
function checkBadges(){
  BADGES.forEach(b=>{ if(!state.badges.includes(b.id) && b.ok(state)){ state.badges.push(b.id); store.set(state); queueCelebration({badge:b.id}); } });
}
/* XP : uniquement pour ce qu'on apprend. */
function xpFor(opt, score, won){
  if(opt.daily) return score*10;
  if(opt.notion!=null) return (score===1 && !(state.notions||[]).includes(opt.notion)) ? 15 : 0;
  if(!opt.id) return 0;
  const key = opt.id+":"+opt.lv; state.cleared = state.cleared||[];
  const first = !state.cleared.includes(key);
  if(won && first){ state.cleared.push(key); return score*LEVELS[opt.lv].xp + [20,40,80,160,240][opt.lv]; }
  return first ? score*Math.ceil(LEVELS[opt.lv].xp/2) : score;
}
MISSION_POOL.splice(0, MISSION_POOL.length,
  {k:"lvl",n:2,t:"Réussir 2 niveaux de parcours"},
  {k:"notion",n:2,t:"Valider 2 notions"},
  {k:"daily",n:3,t:"Répondre 3 fois à la question du jour"},
  {k:"expert",n:1,t:"Réussir un niveau Expert"},
  {k:"terms",n:5,t:"Découvrir 5 définitions"},
  {k:"disc",n:3,t:"Réussir la Découverte de 3 pays"});
(()=>{ const b = BADGES.find(x=>x.id==="explore"); if(b){ b.n = "Lexique vivant"; b.d = "Découvrir 15 définitions"; b.ok = s=>(s.termsSeen||[]).length>=15; } })();
function week(){
  const id = weekId();
  if(!state.week || state.week.id!==id || state.week.v!==7){
    let h = 0; for(const ch of id) h = (h*31+ch.charCodeAt(0))>>>0;
    const pick = []; const pool = MISSION_POOL.slice(); while(pick.length<3){ const k = h % pool.length; pick.push(pool.splice(k,1)[0].k); h = (h*1103515245+12345)>>>0; }
    const keep = state.week && state.week.id===id ? state.week : null;
    state.week = {id, v:7, m:pick, c:keep?keep.c:{}, done:[], seen:keep?keep.seen:[], ln:keep?.ln||[], lc:keep?.lc||[]};
  }
  return state.week;
}
function bump(k, uniq){
  const w = week();
  if(!MISSION_POOL.some(x=>x.k===k)) return;
  if(uniq!=null){ const u = k+":"+uniq; if(w.seen.includes(u)) return; w.seen.push(u); }
  w.c[k] = (w.c[k]||0)+1;
  for(const mk of w.m){ const M = MISSION_POOL.find(x=>x.k===mk); if(!w.done.includes(mk) && (w.c[mk]||0)>=M.n){ w.done.push(mk); const before=levelInfo().l; state.xp += 40; toast(t("Défi réussi : {x} · +40 XP",{x:t(M.t)})); if(levelInfo().l>before) queueCelebration({level:levelInfo().l}); } }
  save();
}
function learned(kind, x){
  const w = week(), arr = kind==="notion" ? w.ln : w.lc;
  if(!arr.includes(x)) arr.push(x);
}
function missionsHTML(){
  const w = week();
  return `<div class="missions">${w.m.map(mk=>{ const M = MISSION_POOL.find(x=>x.k===mk), c = Math.min(M.n, w.c[mk]||0), ok = w.done.includes(mk);
    return `<div class="mission ${ok?"ok":""}"><div class="mring" style="--p:${c/M.n}"><span>${ok?"✓":`${c}/${M.n}`}</span></div><div><b>${esc(t(M.t))}</b><span>${ok?t("Réussi · +40 XP"):"+40 XP"}</span></div></div>`; }).join("")}</div>`;
}
function streakHTML(){
  const log = state.dailyLog||[], days = [];
  for(let i=6;i>=0;i--){ const d = new Date(Date.now()-i*86400000); days.push({d, on: log.includes(d.toDateString())}); }
  const J = LANG==="en" ? ["S","M","T","W","T","F","S"] : ["D","L","M","M","J","V","S"];
  return `<div class="streakbox"><div class="flame ${state.streak>0?"on":""}"><svg viewBox="0 0 24 24"><path d="M12 2c1 4 5 5.5 5 10a5 5 0 0 1-10 0c0-2 1-3.5 2-4.5 0 2 1 3 2 3-1-3 0-6 1-8.5z"/></svg><b>${state.streak}</b></div>
    <div class="sdays">${days.map(x=>`<span class="${x.on?"on":""}"><i></i>${J[x.d.getDay()]}</span>`).join("")}</div></div>`;
}
/* Définitions découvertes : on apprend un mot. */
function showTerm(el){
  const k = +el.dataset.t, [,n,d] = TERMS[k];
  pop.innerHTML = `<b>${esc(n)}</b><span>${esc(d)}</span>`;
  const r = el.getBoundingClientRect(), w = Math.min(300, innerWidth-24);
  pop.style.width = w+"px";
  let x = Math.min(Math.max(12, r.left + r.width/2 - w/2), innerWidth - w - 12);
  pop.style.left = x+"px"; pop.style.top = (r.bottom + 8)+"px";
  pop.classList.add("show"); popFor = el;
  requestAnimationFrame(()=>{ const pr = pop.getBoundingClientRect(); if(pr.bottom > innerHeight-10) pop.style.top = (r.top - pr.height - 8)+"px"; });
  state.termsSeen = state.termsSeen||[];
  if(!state.termsSeen.includes(k)){ state.termsSeen.push(k); bump("terms", k); checkBadges(); }
}

/* ---------- Compteur collectif : ce que la communauté a appris ---------- */
const NOTION_WHAT = ["la différence entre réfugié et déplacé","ce qu'est un génocide","comment on classe une famine","d'où viennent des frontières tracées par d'autres","qui juge les crimes internationaux","ce que sont les lois de la guerre","ce qu'est l'apatridie"];
let PULSE = null;
async function loadPulse(){
  const w = week();
  if(!cloudReady){ PULSE = {local:true, docs:[{ln:w.ln, lc:w.lc}]}; return PULSE; }
  try{
    const qs = await DB.collection("pulse").where("w","==",w.id).get();
    PULSE = {local:false, docs:qs.docs.map(d=>d.data())};
  }catch(e){ PULSE = {local:true, docs:[{ln:w.ln, lc:w.lc}]}; }
  return PULSE;
}
function pulseHTML(P){
  const docs = (P&&P.docs||[]).filter(d=>(d.ln||[]).length||(d.lc||[]).length);
  if(!docs.length) return `<div class="pempty"><b>${t("Le compteur de la semaine est à zéro.")}</b><p>${t("Valide une notion ou réussis un parcours pour le lancer.")}</p></div>`;
  const nc = {}, cc = {};
  docs.forEach(d=>{ (d.ln||[]).forEach(i=>nc[i]=(nc[i]||0)+1); (d.lc||[]).forEach(id=>cc[id]=(cc[id]||0)+1); });
  const people = n => n>1 ? t("{n} personnes",{n:n.toLocaleString(LOC)}) : t("1 personne");
  const lines = [
    ...Object.entries(nc).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([i,n])=>`<li><b>${people(n)}</b> ${n>1?t("ont appris"):t("a appris")} ${esc(t(NOTION_WHAT[i]))}.</li>`),
    ...Object.entries(cc).sort((a,b)=>b[1]-a[1]).slice(0,3).filter(([id])=>C[id]).map(([id,n])=>`<li><b>${people(n)}</b> ${n>1?t("ont réussi un parcours sur"):t("a réussi un parcours sur")} ${esc(C[id].short)}.</li>`)];
  return `<div class="pbig"><b>${docs.length.toLocaleString(LOC)}</b><span>${docs.length>1?t("personnes ont appris quelque chose sur Sankofa cette semaine."):t("personne a appris quelque chose sur Sankofa cette semaine.")}</span></div>
    <ul class="plines">${lines.join("")}</ul>
    <p class="src">${P.local?t("Pour l'instant, ce compteur ne voit que ton appareil. Il deviendra collectif avec les comptes."):t("Compté sans aucun nom : seul le nombre de personnes est gardé.")}</p>`;
}
async function renderPulse(el){
  if(!el) return;
  el.innerHTML = pulseHTML(PULSE || {local:true,docs:[{ln:week().ln,lc:week().lc}]});
  const P = await loadPulse(); if(document.body.contains(el)) el.innerHTML = pulseHTML(P);
}
function renderLeaderboard(){ renderPulse($("#leader")); }

/* ---------- Apprendre ---------- */
function renderLearn(){
  const all = FEATURED.flatMap(id=>Q[id].d.concat(Q[id].i).map(q=>({...q,id})));
  const day = Math.floor(Date.now()/86400000), q = all[day % all.length];
  const done = state.lastDaily===new Date().toDateString();
  $("#learnTop").innerHTML = `<div class="card ltop"><div><div class="eyebrow">${t("Ta série")}</div>${streakHTML()}</div><div><div class="eyebrow">${t("Défis de la semaine")}</div>${missionsHTML()}</div></div>
    <div class="card pulsec" style="margin-bottom:14px"><div class="eyebrow">${t("Ensemble cette semaine")}</div><div id="pulseLearn"></div></div>`;
  renderPulse($("#pulseLearn"));
  $("#daily").innerHTML = `<div class="dhead"><div class="eyebrow">${t("Question du jour")} · ${esc(C[q.id].short)}</div><span class="streak">+10 XP</span></div><div id="dq" style="margin-top:14px"></div>`;
  if(done) $("#dq").innerHTML = `<p style="margin:0">${t("Tu as déjà répondu aujourd'hui. Reviens demain pour garder ta série.")}</p>`;
  else runQuiz($("#dq"),[q],{daily:true});
  $("#courses").innerHTML = FEATURED.map(id=>{
    const c = C[id], r = state.stamps[id]?.r||0;
    return `<a class="course" href="#quiz-${c.slug}"><canvas data-sil="${id}" data-col="${mainLayer(c).hex}"></canvas>
      <span><b>${esc(c.short)}</b><span class="pips">${rList(id).map(k=>`<i style="background:${r>=k?RARITY[k].col:"rgba(var(--ink-rgb),.1)"}"></i>`).join("")} ${r?RARITY[r].name:t("Pas encore de tampon")}</span></span>
      <span class="st">${r>=topLv(id)+1?RARITY[r].name:r?t("Continuer"):t("Commencer")}</span></a>`;
  }).join("");
  $("#courses").querySelectorAll("canvas[data-sil]").forEach(cv=>silhouette(cv,cv.dataset.sil,cv.dataset.col,{pad:.1,step:4}));
  const nv = state.notions||[];
  $("#notions").innerHTML = NOTIONS.map((n,i)=>`<button class="notion ${nv.includes(i)?"ok":""}" data-i="${i}" style="--c:${n.c}"><span class="nnum">${String(i+1).padStart(2,"0")}</span><b>${esc(n.t)}</b><span class="nst">${nv.includes(i)?t("Validée"):"5 min"}</span></button>`).join("");
  $("#notions").querySelectorAll(".notion").forEach(b=>b.onclick=()=>openNotion(+b.dataset.i));
  $("#lexique").innerHTML = LEXIQUE.map(([tt,d])=>`<details class="lex"><summary>${tt}</summary><p>${esc(d)}</p></details>`).join("");
  $("#agir").innerHTML = AGIR.map(([n,d,u])=>`<a class="agir" href="${u}" target="_blank" rel="noopener"><b>${n}</b><span>${d}</span></a>`).join("");
}
function openNotion(i){
  const n = NOTIONS[i], m = $("#modal");
  m.innerHTML = `<div class="mbox" role="dialog" aria-modal="true" aria-labelledby="nT"><button class="mclose" aria-label="${t("Fermer")}">×</button>
    <div class="eyebrow" style="color:${n.c}">${t("Notion {a} sur {b}",{a:i+1,b:NOTIONS.length})}</div><h2 id="nT">${esc(n.t)}</h2><p class="lesson">${gl(n.x,3)}</p>${n.s?srcd([n.s]):""}
    <div class="eyebrow" style="margin:18px 0 10px">${t("Vérifie")}</div><div id="nq"></div></div>`;
  m.classList.add("show");
  const close=()=>{ m.classList.remove("show"); renderLearn(); };
  m.querySelector(".mclose").onclick=close; m.onclick=e=>{ if(e.target===m) close(); };
  runQuiz($("#nq"),[n.q],{notion:i});
}

/* ---------- Passeport ---------- */
function renderPass(){
  const n = Object.keys(state.stamps).length, LI = levelInfo(), lv = LI.l, into = LI.into;
  const counts = [1,2,3,4,5].map(r=>Object.values(state.stamps).filter(s=>s.r===r).length);
  $("#passHead").innerHTML = `<div class="pcover">
      <div class="phid">${state.profile?avatarSVG(state.profile,64):""}<div><div class="eyebrow">${t("Passeport Sankofa")}${state.profile?" · "+esc(state.profile.name):""}</div><h2>${esc(title())}</h2>
      <div class="lvline"><span>${t("Niveau {n}",{n:lv})}</span><div class="xpbar"><i style="width:${into/LI.need*100}%"></i></div><span>${into} / ${LI.need} XP${lv<XP_THR.length?" · "+(TITLES[lv].split(" ")[0]!==TITLES[lv-1].split(" ")[0]?t("avant {x}",{x:esc(TITLES[lv])}):t("avant le niveau {n}",{n:lv+1})):""}</span></div></div></div>
      ${passEmblem()}
    </div>
    <div class="stats"><div><b>${n}/${FEATURED.length}</b><span>${t("escales tamponnées")}</span></div><div><b>${state.xp}</b><span>${t("points d'expérience")}</span></div><div><b>${(state.notions||[]).length}/${NOTIONS.length}</b><span>${t("notions validées")}</span></div><div><b>${(state.dossiers||[]).length}/${Object.keys(DOSSIERS).length}</b><span>${t("dossiers lus")}</span></div><div><b>${state.streak}</b><span>${t("jours de série")}</span></div><div><b>${state.badges.length}/${BADGES.length}</b><span>${t("badges")}</span></div></div>
    <p class="xpnote">${t("Les points d'expérience récompensent ce que tu apprends : parcours, notions, question du jour. Jamais le simple fait d'ouvrir une fiche.")}</p>`;
  $("#passId").innerHTML = state.profile ? `<div class="pidwrap">${idCardHTML(state.profile)}<div class="pidside"><div class="eyebrow">${t("Cette semaine")}</div>${streakHTML()}${missionsHTML()}<div class="pact"><button class="cta ghost" id="pEdit">${t("Modifier mon identité")}</button><button class="cta ghost" id="pShare">${t("Partager ma carte")}</button></div></div></div>`
    : `<div class="card pidempty"><div>${avatarSVG({fg:1,bg:1,egg:3},72)}</div><div><h3>${t("Crée ton identité de voyageur")}</h3><p>${t("Ton emblème, ta cause, ton pays de cœur. Ton passeport devient le tien.")}</p></div><button class="cta" id="pCreate">${t("Créer mon passeport")}</button></div>`;
  const pc=$("#pCreate"); if(pc) pc.onclick=()=>openOnboarding(false);
  const pe=$("#pEdit"); if(pe) pe.onclick=()=>openOnboarding(true);
  const psh=$("#pShare"); if(psh) psh.onclick=()=>shareCard("id",state.profile.heart||FEATURED[0]);
  $("#tiers").innerHTML = [1,2,3,4,5].map(r=>`<div class="tier r${r}"><i style="background:${RARITY[r].col}"></i><b>${RARITY[r].name}</b><span>${RARITY[r].how}</span><em>${counts[r-1]}</em></div>`).join("");
  const dnum = d=>{ const m = String(d||"").split("/"); return m.length===3 ? +(m[2]+m[1].padStart(2,"0")+m[0].padStart(2,"0")) : 0; };
  const won = FEATURED.filter(id=>state.stamps[id]).sort((a,b)=>(state.stamps[b].r-state.stamps[a].r) || (dnum(state.stamps[b].d)-dnum(state.stamps[a].d)));
  const todo = FEATURED.filter(id=>!state.stamps[id]).sort((a,b)=>C[a].short.localeCompare(C[b].short, LANG));
  const SF = window.STAMP_FILTER || "all";
  const sfl = [["all",t("Tous"),FEATURED.length],["won",t("Obtenus"),won.length],["todo",t("À conquérir"),todo.length]];
  const stf = $("#stampFilt") || (()=>{ $("#stamps").insertAdjacentHTML("beforebegin", `<div class="stfilt" id="stampFilt" role="group" aria-label="${t("Filtrer les tampons")}"></div>`); return $("#stampFilt"); })();
  stf.innerHTML = sfl.map(([k,l,n])=>`<button type="button" data-sf="${k}" aria-pressed="${SF===k}">${l} <em>${n}</em></button>`).join("");
  stf.querySelectorAll("[data-sf]").forEach(b=>b.onclick=()=>{ window.STAMP_FILTER = b.dataset.sf; renderPass(); });
  $("#stamps").innerHTML = (SF==="won" ? won : SF==="todo" ? todo : won.concat(todo)).map(id=>{
    const c=C[id], s=state.stamps[id];
    return s?`<div class="slot">${stampSVG(id,s.r,s.d)}<span>${esc(c.short)}</span><button class="slotshare" data-id="${id}">${t("Partager")}</button></div>`
            :`<a class="slot locked" href="#quiz-${c.slug}">${GHOST(id)}<span>${esc(c.short)} · ${t("à conquérir")}</span></a>`;
  }).join("") || `<p class="clsmall">${t("Aucun tampon pour l'instant. Réussis un parcours pour gagner le premier.")}</p>`;
  $("#cards").innerHTML = FEATURED.map(id=>{ const f0=(C[id].figs||[]).find(f=>f.n)||(C[id].figs||[])[0]||{}, D=(DEEP[id]&&DEEP[id].fig)?DEEP[id]:{fig:{n:f0.n||C[id].short, d:f0.at?fmtAt(f0.at):"", t:String(f0.d||f0.t||"").replace(/<[^>]+>/g,"")}}, s=state.stamps[id], col = s?RARITY[s.r].col:"#9AA0A6";
    return s?`<div class="mcard" style="--c:${col}"><div class="mtop"><span class="eyebrow">${esc(C[id].short)}</span><span class="mr">${RARITY[s.r].name}</span></div><b>${esc(D.fig.n)}</b><span class="fd">${esc(D.fig.d)}</span><p>${esc(D.fig.t)}</p></div>`
            :`<a class="mcard locked" href="#quiz-${C[id].slug}"><div class="mtop"><span class="eyebrow">${esc(C[id].short)}</span>${LOCK}</div><b>${t("Carte mémoire")}</b><p>${t("Gagne un tampon {x} pour découvrir cette carte.",{x:esc(C[id].short)})}</p></a>`; }).join("");
  document.querySelectorAll(".slotshare").forEach(b=>b.onclick=()=>shareCard("stamp",b.dataset.id));
  renderPulse($("#leader"));
  $("#badges").innerHTML = BADGES.map(b=>{ const on = state.badges.includes(b.id);
    return `<div class="badge ${on?"on":""}"><span class="bico">${on?"★":"☆"}</span><b>${esc(t(b.n))}</b><span>${esc(t(b.d))}</span></div>`; }).join("");
  if(hasCele()) setTimeout(()=>{ if(location.hash==="#passeport") celebrate(); },450);
}
function passEmblem(){
  const txt = LANG==="en" ? "PASSPORT · SANKOFA · ATLAS OF PEOPLES IN HARDSHIP ·" : "PASSEPORT · SANKOFA · ATLAS DES PEUPLES ÉPROUVÉS ·";
  return `<svg class="emblem" viewBox="0 0 120 120" aria-hidden="true"><defs><path id="embP" d="M60,60 m-47,0 a47,47 0 1,1 94,0 a47,47 0 1,1 -94,0"/></defs>
  <circle cx="60" cy="60" r="56" fill="none" stroke="#C8962E" stroke-width="1.6"/><circle cx="60" cy="60" r="38" fill="none" stroke="#C8962E" stroke-width=".8" stroke-dasharray="2 3"/>
  <text font-family="Geist Mono, monospace" font-size="${LANG==="en"?6.4:7.2}" letter-spacing="2.2" fill="#C8962E"><textPath href="#embP">${txt}</textPath></text>
  <g transform="translate(37 35) scale(1.45)"><path d="M4.5 17.5 1.8 13.2l4.4 2.1z" fill="#C8962E"/><ellipse cx="14.5" cy="20" rx="9.5" ry="6.2" transform="rotate(-12 14.5 20)" fill="#C8962E"/><path d="M21.5 17.2C25.8 11 21 4.6 15.4 7.4" fill="none" stroke="#C8962E" stroke-width="3.4" stroke-linecap="round"/><circle cx="14.6" cy="8.6" r="3.3" fill="#C8962E"/><path d="M12.2 10.3 10.3 13.4l3.4-1.6z" fill="#C8962E"/><ellipse cx="11.6" cy="14.6" rx="2.5" ry="1.9" fill="#F2F0EA"/><circle cx="15.6" cy="7.9" r=".9" fill="#121A33"/><path d="M12.5 25.5v4M17 25v4.5" stroke="#C8962E" stroke-width="1.6" stroke-linecap="round"/></g></svg>`;
}

/* ---------- Recherche, routes de l'exil ---------- */
function search(){
  const v = norm(q.value.trim());
  const matches = !v ? FEATURED.map(id=>C[id]) : Object.values(C).filter(c=>norm(c.name+" "+c.short+" "+c.region+" "+c.alias).includes(v));
  sel = 0;
  res.innerHTML = matches.length ? matches.slice(0,8).map((c,i)=>`<button class="res" role="option" aria-selected="${i===sel}" data-id="${c.id}"><span class="rn">${esc(c.name)}</span><span class="dots">${dotsFor(c)}</span><span class="rr">${esc(c.region)}</span></button>`).join("")
    : `<div class="res-empty">${t("Ce pays n'est pas encore dans l'atlas.")}</div>`;
  res.querySelectorAll(".res").forEach(b=>b.onmousedown=e=>{e.preventDefault();go(b.dataset.id);});
  res.classList.add("show"); box.setAttribute("aria-expanded","true");
}
/* ---------- Routage ---------- */
function route(){
  const h = location.hash.slice(1) || "globe";
  let v = h, id = null;
  if(h.startsWith("pays-")){ id = bySlug[h.slice(5)]; v = id?"pays":"globe"; }
  if(h.startsWith("quiz-")){ id = bySlug[h.slice(5)]; v = id && C[id].quiz ? "quiz" : "globe"; }
  if(h==="methode"){ v = "globe"; setTimeout(()=>$("#methode").scrollIntoView({behavior:"smooth"}),60); }
  if(!["globe","explorer","apprendre","actu","passeport","pays","quiz","sources","mentions","confidentialite","apropos","presse"].includes(v)) v="globe";
  if(tourOn && v!=="globe") tourEnd();
  $("#modal").classList.remove("show"); closeSettings();
  document.querySelectorAll(".view").forEach(s=>s.classList.toggle("on",s.id==="v-"+v));
  document.body.classList.toggle("focus", v==="quiz");
  document.querySelectorAll("[data-v]").forEach(a=>{ if(a.dataset.v===v) a.setAttribute("aria-current","page"); else a.removeAttribute("aria-current"); });
  if(v==="pays") renderPays(id);
  if(v==="quiz") renderQuizView(id);
  if(v==="explorer") renderExplorer();
  if(v==="apprendre") renderLearn();
  if(v==="actu") renderActu();
  if(v==="passeport") renderPass();
  if(v==="sources") renderSources();
  if(v==="mentions") renderLegal("mentions");
  if(v==="confidentialite") renderLegal("confidentialite");
  if(v==="apropos") renderLegal("apropos");
  if(v==="presse") renderLegal("presse");
  if(v==="globe"){ renderRail(); gResize(); }
  if(h!=="methode") window.scrollTo({top:0,behavior:"instant"});
}
function renderSources(){
  const old = [];
  LAYERS.forEach(l=>{ if(l.at && isOld(l.at)) old.push([l.name, l.at, l.src[0]]); });
  Object.values(C).forEach(c=>c.figs.forEach(f=>{ if(f.n && f.at && isOld(f.at)) old.push([c.short+" · "+f.n, f.at, f.s]); }));
  $("#sourceIntro").innerHTML = `<p>${t("Chaque donnée de Sankofa renvoie à un rapport d'agence des Nations unies, de juridiction internationale, d'organisation spécialisée ou de presse de référence. Chaque chiffre porte la date à laquelle il s'applique. Dernière vérification : {d}.",{d:fmtDay(VERIFIED)})}</p>
    ${old.length?`<details class="card oldlist"><summary class="eyebrow">${t("À surveiller · {n} chiffres anciens",{n:old.length})}</summary><p>${t("Ces chiffres datent de plus de 18 mois. Ce sont les plus récents publiés par leur source : ils seront remplacés dès la prochaine édition.")}</p><ul>${old.map(([n,a,s])=>`<li><b>${esc(n)}</b><span>${esc(fmtAt(a))} · ${esc(S[s].t)}</span></li>`).join("")}</ul></details>`:""}`;
  $("#sourceList").innerHTML = Object.keys(S).map(k=>`<p>${link(k)}</p>`).join("");
}

/* Date de dernière mise à jour d'une fiche : le chiffre ou l'actualité la plus récente */
function updOf(id){
  const c = C[id], today = new Date().toISOString().slice(0,10); let best = "";
  for(const f of (c.figs||[])){ const a = f.at; if(!a) continue;
    const k = a[0]==="Y" ? a.slice(1)+"-12" : a[0]==="M" ? a.slice(1,8) : a.slice(0,7); if(k > best && k <= today.slice(0,7)) best = k; }
  if(typeof FIL!=="undefined") for(const n of FIL){ if(n.id===id && n.d <= today && n.d.slice(0,7) > best) best = n.d.slice(0,7); }
  if(!best) return "";
  const [y,m] = best.split("-").map(Number);
  return (LANG==="en" ? MOIS_EN : MOIS_FR)[m-1] + " " + y;
}
