      <div class="srow static col"><span class="sico">${ico("moon")}</span><span class="slab">${t("Apparence")}</span>${seg("theme",[["light",t("Clair")],["dark",t("Sombre")],["auto",t("Auto")]],PREFS.theme)}</div>
