/* ================= Performance (v10) =================
   Principe : on ne redessine que ce qui bouge, et seulement ce qui se voit. */

/* ---------- Globe : fond mis en cache, pulsations par-dessus ---------- */
/* var plutôt que const : ces fonctions peuvent être appelées avant que ce fichier ne s'exécute */
var F110D = null, LAND110 = null, MESH110 = null, gb = null, bx = null, bpath = null, baseSig = "", autoRot = false, lastT = 0;
function initBase(){ if(gb) return; LAND110 = topojson.merge(TOPO, TOPO.objects.countries.geometries); MESH110 = topojson.mesh(TOPO, TOPO.objects.countries); F110D = {}; F110.forEach(f=>{ if(C[f.id]) F110D[f.id] = f; }); gb = document.createElement("canvas"); bx = gb.getContext("2d"); bpath = d3.geoPath(proj, bx); }
function makeGrads(){
  if(!TH) readTheme(); initBase();
  const r = proj.scale(), [cx,cy] = proj.translate();
  const halo = bx.createRadialGradient(cx,cy,r*.95,cx,cy,r*1.12); halo.addColorStop(0,TH.halo); halo.addColorStop(1,TH.halo0);
  const sea = bx.createRadialGradient(cx-r*.35,cy-r*.4,r*.1,cx,cy,r); sea.addColorStop(0,TH.sea0); sea.addColorStop(1,TH.sea1);
  const sh = bx.createRadialGradient(cx-r*.3,cy-r*.35,r*.6,cx,cy,r*1.02); sh.addColorStop(0,"rgba(0,0,0,0)"); sh.addColorStop(1,TH.shade);
  grads = {halo,sea,sh,r,cx,cy}; baseSig = ""; cacheOk = false;
  /* calques fixes (halo + océan, ombre) : peints une fois, recopiés ensuite */
  const mk = ()=>{ const cv = document.createElement("canvas"); cv.width = Math.ceil(GW*GDPR); cv.height = Math.ceil(GW*GDPR); const x = cv.getContext("2d"); x.setTransform(GDPR,0,0,GDPR,0,0); return [cv,x]; };
  const [bgc,bgx] = mk(), [shc,shx] = mk();
  const h2 = bgx.createRadialGradient(cx,cy,r*.95,cx,cy,r*1.12); h2.addColorStop(0,TH.halo); h2.addColorStop(1,TH.halo0);
  const s2 = bgx.createRadialGradient(cx-r*.35,cy-r*.4,r*.1,cx,cy,r); s2.addColorStop(0,TH.sea0); s2.addColorStop(1,TH.sea1);
  bgx.fillStyle = h2; bgx.beginPath(); bgx.arc(cx,cy,r*1.12,0,6.283); bgx.fill();
  bgx.fillStyle = s2; bgx.beginPath(); bgx.arc(cx,cy,r,0,6.283); bgx.fill();
  const g3 = shx.createRadialGradient(cx-r*.3,cy-r*.35,r*.6,cx,cy,r*1.02); g3.addColorStop(0,"rgba(0,0,0,0)"); g3.addColorStop(1,TH.shade);
  shx.fillStyle = g3; shx.beginPath(); shx.arc(cx,cy,r,0,6.283); shx.fill();
  grads.bgc = bgc; grads.shc = shc; grads.dpr = GDPR; grads.gw = GW;
}
function blit(c, cv){ c.save(); c.setTransform(1,0,0,1,0,0); c.drawImage(cv,0,0); c.restore(); }
var cacheOk = false;
function drawBase(c, path, lite){
  const {r,cx,cy} = grads;
  proj.precision(lite ? 0 : .7);
  const fixed = grads.bgc && zk<1.6 && grads.gw===GW && proj.scale()===r;
  if(fixed) blit(c, grads.bgc);
  else { if(zk<1.6){ c.fillStyle = grads.halo; c.beginPath(); c.arc(cx,cy,r*1.12,0,6.283); c.fill(); }
    c.beginPath(); path(sphere); c.fillStyle = grads.sea; c.fill(); }
  if(!lite){ c.beginPath(); path(grat); c.strokeStyle = TH.grat; c.lineWidth = .6; c.stroke(); }
  c.fillStyle = TH.land; c.strokeStyle = TH.landLine; c.lineWidth = .5;
  if(!lite && zk>=1.9){ c.beginPath(); for(const f of F50) path(f); c.fill(); c.stroke(); }
  else if(lite){ c.beginPath(); path(LAND110); c.fill(); c.beginPath(); path(MESH110); c.stroke(); }
  else { c.beginPath(); path(LAND110); c.fill(); c.beginPath(); path(MESH110); c.stroke(); }
  const fine = !lite && zk>=1.6, ctr = [-rot[0],-rot[1]], groups = {};
  /* un seul tracé par couleur, et on ignore les pays de la face cachée */
  for(const f of DATA_F){
    const col = fillFor(f.id); if(!col) continue;
    if(d3.geoDistance(centroid(f.id), ctr) > 2.1) continue;
    (groups[col] = groups[col] || []).push(f);
  }
  c.strokeStyle = TH.dataLine; c.lineWidth = .6;
  for(const col in groups){
    c.beginPath(); for(const f of groups[col]) path(fine ? f : (F110D[f.id]||f));
    c.fillStyle = col; c.fill(); if(!lite) c.stroke();
  }
  if(hover && fillFor(hover)){ const f = (fine ? featById[hover] : F110D[hover]) || featById[hover]; if(f){ c.beginPath(); path(f); c.strokeStyle = TH.ink; c.lineWidth = 1.4; c.stroke(); } }
  if(fixed) blit(c, grads.shc); else { c.beginPath(); path(sphere); c.fillStyle = grads.sh; c.fill(); }
  proj.precision(.7);
}
function gDraw(now){
  if(!grads) makeGrads();
  const lite = moving || !!anim || autoRot;
  const sig = rot[0].toFixed(2)+","+rot[1].toFixed(2)+","+proj.scale().toFixed(1)+","+active+","+hover+","+routesOn+","+lite+","+GW+","+(MIX?"m"+SPOT:"");
  gx.setTransform(1,0,0,1,0,0); gx.clearRect(0,0,gc.width,gc.height); gx.setTransform(GDPR,0,0,GDPR,0,0);
  if(sig!==baseSig){
    // le fond change : on le dessine directement à l'écran (pas de copie)
    drawBase(gx, gpath, lite); baseSig = sig; cacheOk = false;
  } else {
    // le fond est stable : on le met en cache une fois, puis on le recopie
    if(!cacheOk){ if(gb.width!==gc.width || gb.height!==gc.height){ gb.width = gc.width; gb.height = gc.height; } bx.setTransform(GDPR,0,0,GDPR,0,0); bx.clearRect(0,0,GW,GW); drawBase(bx, bpath, lite); cacheOk = true; }
    gx.setTransform(1,0,0,1,0,0); gx.drawImage(gb,0,0); gx.setTransform(GDPR,0,0,GDPR,0,0);
  }
  const center = [-rot[0],-rot[1]], hex = L(active).hex, k = ((now||0)%1800)/1800;
  if(MIX){
    /* mode « Tout » : un point par pays, à la couleur de sa crise ; le pays en vedette émet des ondes */
    const byCol = {};
    for(const id in C){
      if(!featById[id] || !fillFor(id)) continue;
      const c = centroid(id); if(d3.geoDistance(c,center)>1.5) continue;
      const p = proj(c); if(!p) continue; const col = mainLayer(C[id]).hex;
      (byCol[col] = byCol[col] || []).push(p);
    }
    for(const col in byCol){ gx.beginPath(); for(const p of byCol[col]){ gx.moveTo(p[0]+3,p[1]); gx.arc(p[0],p[1],3,0,6.283); } gx.fillStyle = col; gx.fill(); }
    if(SPOT && featById[SPOT]){
      const c = centroid(SPOT), p = d3.geoDistance(c,center)<1.5 ? proj(c) : null;
      if(p){ const col = mainLayer(C[SPOT]).hex, t2 = ((now||0) - SPOT_T)/1000;
        for(let j=0;j<2;j++){ const kk = ((t2+j*.45)%1.1)/1.1; gx.beginPath(); gx.arc(p[0],p[1],5+kk*26,0,6.283); gx.strokeStyle = col; gx.globalAlpha = (1-kk)*.85; gx.lineWidth = 2; gx.stroke(); }
        gx.globalAlpha = 1; gx.beginPath(); gx.arc(p[0],p[1],5.5,0,6.283); gx.fillStyle = col; gx.fill(); gx.strokeStyle = "#fff"; gx.lineWidth = 1.5; gx.stroke(); }
    }
  } else {
  gx.fillStyle = hex; gx.beginPath();
  const ring = [];
  for(const id in C){
    if(!C[id].layers[active] || !featById[id]) continue;
    const c = centroid(id); if(d3.geoDistance(c,center)>1.5) continue;
    const p = proj(c); if(!p) continue;
    gx.moveTo(p[0]+3,p[1]); gx.arc(p[0],p[1],3,0,6.283); ring.push(p);
  }
  gx.fill();
  if(!moving && !autoRot && ring.length){ gx.beginPath(); for(const p of ring){ gx.moveTo(p[0]+3+k*12,p[1]); gx.arc(p[0],p[1],3+k*12,0,6.283); } gx.strokeStyle = hex; gx.globalAlpha = (1-k)*.7; gx.lineWidth = 1.2; gx.stroke(); gx.globalAlpha = 1; }
  }
  for(let i=ripples.length-1;i>=0;i--){
    const rp = ripples[i], age = (now-rp.t)/1600;
    if(age>1){ ripples.splice(i,1); continue; }
    const c = centroid(rp.id); if(d3.geoDistance(c,center)>1.5) continue;
    const p = proj(c); if(!p) continue;
    gx.beginPath(); gx.arc(p[0],p[1],4+age*26,0,6.283);
    gx.strokeStyle = "#7A55F5"; gx.globalAlpha = (1-age)*.9; gx.lineWidth = 2; gx.stroke(); gx.globalAlpha = 1;
  }
  drawFocus(now, center);
  if(routesOn) drawRoutes(now, center);
  dirty = false; lastDraw = now;
}
function gLoop(now){
  const dt = Math.min(64, now - (lastT||now)); lastT = now;
  if(gVisible() && inView){
    const ar = !reduce && !anim && !tourOn && !routesOn && now-lastI>2500 && !hover && zk<1.2;
    if(ar){ rot[0] += 0.05*dt/16.7; proj.rotate(rot); }
    if(ar!==autoRot){ autoRot = ar; dirty = true; }
    // Geste ou animation : chaque image. Rotation lente et pulsations : 30 images par seconde.
    if(moving || anim || (dirty && !ar) || now-lastDraw>=32) gDraw(now);
  }
  requestAnimationFrame(gLoop);
}

/* ---------- Boucles d'animation qui s'arrêtent quand on ne les voit plus ---------- */
var VIS = null, visIO = null, VL = null;
/* La boucle ne tourne que si le dessin est à l'écran ; elle s'arrête complètement sinon, et repart quand il revient. */
function vlKick(cv){
  const o = cv._vl; if(!o || o.running) return; o.running = true;
  (function loop(t){
    if(!cv.isConnected){ visIO.unobserve(cv); VL.delete(cv); o.running = false; return; }
    if(!VIS.get(cv) || document.hidden){ o.running = false; return; }
    if(t - o.last >= 1000/o.fps - 2){ o.last = t; o.render(t); }
    requestAnimationFrame(loop);
  })(performance.now());
}
function visLoop(canvas, fps, render){
  if(!visIO){ VIS = new WeakMap(); VL = new Set();
    visIO = new IntersectionObserver(es=>es.forEach(e=>{ VIS.set(e.target, e.isIntersecting); if(e.isIntersecting) vlKick(e.target); }));
    document.addEventListener("visibilitychange", ()=>{ if(!document.hidden) VL.forEach(vlKick); }); }
  canvas._vl = {fps, render, last:0, running:false}; VL.add(canvas); visIO.observe(canvas);
}

/* ---------- Silhouette en points : un seul tracé par niveau de lumière ---------- */
var lazyIO = null;
function silhouette(canvas,id,color,opts={}){
  const f = featById[id]; if(!f) return;
  /* cartes statiques dans une page : dessinées quand elles arrivent à l'écran */
  if(!opts.animate && !opts._now && canvas.closest(".view")){
    if(!lazyIO) lazyIO = new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){ lazyIO.unobserve(e.target); const a = e.target._sil; e.target._sil = null; if(a) silhouette(e.target, a[0], a[1], {...a[2], _now:true}); } }), {rootMargin:"200px"});
    canvas._sil = [id, color, opts]; lazyIO.observe(canvas); return;
  }
  const r = canvas.getBoundingClientRect();
  const w = Math.round(Math.max(60,r.width)), h = Math.round(Math.max(48,r.height));
  canvas.width = w*DPR; canvas.height = h*DPR;
  const ctx = canvas.getContext("2d"); ctx.setTransform(DPR,0,0,DPR,0,0);
  const pad = opts.pad ?? 0.14;
  const pj = d3.geoMercator().rotate([-(CENTER_FIX[f.id]||d3.geoCentroid(f))[0],0]).fitExtent([[w*pad,h*pad],[w*(1-pad),h*(1-pad)]], f);
  const step = opts.step || Math.max(4, Math.round(Math.min(w,h)/34));
  const m = document.createElement("canvas"); m.width = w; m.height = h;
  const mc = m.getContext("2d", {willReadFrequently:true}); mc.beginPath(); d3.geoPath(pj, mc)(f); mc.fillStyle = "#000"; mc.fill();
  const data = mc.getImageData(0,0,w,h).data, pts = [];
  for(let y=step/2;y<h;y+=step) for(let x=step/2;x<w;x+=step) if(data[(Math.floor(y)*w+Math.floor(x))*4+3]>0) pts.push([x,y,Math.random()]);
  if(pts.length<3){ ctx.beginPath(); d3.geoPath(pj, ctx)(f); ctx.fillStyle = color; ctx.fill(); return; }
  const LV = 6, anim = opts.animate && !reduce;
  /* fond du pays : dessiné une fois et mis en cache pour les silhouettes animées */
  let bg = null;
  const drawBg = c=>{ c.beginPath(); d3.geoPath(pj, c)(f); c.fillStyle = color+"14"; c.fill(); };
  if(anim){ bg = document.createElement("canvas"); bg.width = w*DPR; bg.height = h*DPR; const bgx = bg.getContext("2d"); bgx.scale(DPR,DPR); drawBg(bgx); }
  function render(t){
    if(bg){ ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,canvas.width,canvas.height); ctx.drawImage(bg,0,0); ctx.setTransform(DPR,0,0,DPR,0,0); }
    else drawBg(ctx);
    const buckets = Array.from({length:LV}, ()=>[]);
    for(const pt of pts){ const k = opts.animate ? (0.55+0.45*Math.sin(t/900+pt[2]*6.28)) : (0.6+pt[2]*0.4); buckets[Math.min(LV-1, Math.floor(k*LV))].push(pt); }
    ctx.fillStyle = color;
    buckets.forEach((b,i)=>{ if(!b.length) return; const k = (i+.5)/LV, rad = step*0.28*(0.7+0.5*k); ctx.beginPath(); for(const [x,y] of b){ ctx.moveTo(x+rad,y); ctx.arc(x,y,rad,0,6.283); } ctx.globalAlpha = 0.35+0.65*k; ctx.fill(); });
    ctx.globalAlpha = 1;
  }
  render(0);
  if(anim) visLoop(canvas, 24, render);
}

/* ---------- Matrices de points : deux tracés au lieu d'un par point ---------- */
function matrix(canvas,count,color,cols){
  const w = canvas.parentElement.clientWidth || 300;
  cols = cols || Math.max(14, Math.floor(w/11));
  const gap = w/cols, rows = Math.ceil(count/cols), h = rows*gap, rad = gap*0.32;
  canvas.width = w*DPR; canvas.height = h*DPR; canvas.style.height = h+"px";
  const ctx = canvas.getContext("2d"); ctx.setTransform(DPR,0,0,DPR,0,0);
  const start = performance.now(), dur = reduce?0:1200, empty = TH.empty;
  const dots = (a,b,col)=>{ ctx.beginPath(); for(let i=a;i<b;i++){ const x = (i%cols)*gap+gap/2, y = Math.floor(i/cols)*gap+gap/2; ctx.moveTo(x+rad,y); ctx.arc(x,y,rad,0,6.283); } ctx.fillStyle = col; ctx.fill(); };
  function draw(now){
    const k = dur ? Math.min(1,(now-start)/dur) : 1, shown = Math.floor(count*d3.easeCubicOut(k));
    ctx.clearRect(0,0,w,h); dots(0,shown,color); dots(shown,count,empty);
    if(k<1) requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
}

/* ---------- Mini-globe de localisation : fond en cache ---------- */
function drawLocator(id){
  const cv = $("#locCv"); if(!cv) return;
  const S0 = 132, ctx = cv.getContext("2d"); cv.width = S0*DPR; cv.height = S0*DPR;
  const c = centroid(id), pr = d3.geoOrthographic().rotate([-c[0],-c[1]]).translate([S0/2,S0/2]).scale(S0/2-4).clipAngle(90);
  const col = mainLayer(C[id]).hex;
  const bg = document.createElement("canvas"); bg.width = S0*DPR; bg.height = S0*DPR;
  const b = bg.getContext("2d"), pa = d3.geoPath(pr, b); b.setTransform(DPR,0,0,DPR,0,0);
  b.beginPath(); pa({type:"Sphere"}); b.fillStyle = TH.sea1; b.fill();
  b.beginPath(); for(const f of F110) pa(f); b.fillStyle = TH.land; b.fill(); b.strokeStyle = TH.landLine; b.lineWidth = .4; b.stroke();
  b.beginPath(); pa(featById[id]); b.fillStyle = col; b.fill();
  b.beginPath(); pa({type:"Sphere"}); b.strokeStyle = TH.landLine; b.lineWidth = 1; b.stroke();
  const p = pr(c);
  function render(now){
    const k = ((now||0)%1800)/1800;
    ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,cv.width,cv.height); ctx.drawImage(bg,0,0); ctx.setTransform(DPR,0,0,DPR,0,0);
    if(p){ ctx.beginPath(); ctx.arc(p[0],p[1],3,0,6.283); ctx.fillStyle = col; ctx.fill(); ctx.beginPath(); ctx.arc(p[0],p[1],3+k*14,0,6.283); ctx.strokeStyle = col; ctx.globalAlpha = 1-k; ctx.lineWidth = 1.4; ctx.stroke(); ctx.globalAlpha = 1; }
  }
  render(0);
  if(!reduce) visLoop(cv, 30, render);
}

