/* Titres qui s'écrivent */
function splitTitles(root){
  if(reduce) return;
  root.querySelectorAll("h1:not([data-sp])").forEach(h=>{
    h.dataset.sp = 1; let i = 0;
    const w = document.createTreeWalker(h, NodeFilter.SHOW_TEXT), nodes = []; while(w.nextNode()) nodes.push(w.currentNode);
    nodes.forEach(n=>{ const f = document.createDocumentFragment(); n.textContent.split(/(\s+)/).forEach(p=>{ if(!p) return; if(/^\s+$/.test(p)) f.appendChild(document.createTextNode(p)); else { const s = document.createElement("span"); s.className = "w"; s.style.setProperty("--i", i++); s.textContent = p; f.appendChild(s); } }); n.replaceWith(f); });
  });
}

/* Chiffres mécaniques */
let odoIO = null;
function odometers(root){
  if(reduce || !root) return;
  if(!odoIO) odoIO = new IntersectionObserver(es=>es.forEach(en=>{ if(en.isIntersecting){ requestAnimationFrame(()=>en.target.classList.add("go")); odoIO.unobserve(en.target); } }),{threshold:.4});
  root.querySelectorAll(".fig .n:not([data-odo]), .big:not([data-odo])").forEach(el=>{
    const txt = el.textContent; if(!/\d/.test(txt)) return; el.dataset.odo = 1;
    /* Le vrai chiffre reste dans le texte (copie, lecteurs d'écran) ; la bande 0-9 n'est qu'un décor CSS. */
    let k = 0; el.innerHTML = [...txt].map(ch=>/\d/.test(ch)?`<span class="odo" style="--d:${ch};--k:${k++}">${ch}</span>`:esc(ch)).join("");
    odoIO.observe(el);
  });
}
