/* ---------- Alertes de suivi ---------- */
const AL_KEY = "sankofa-alerts";
function alertsOn(){ try{ return localStorage.getItem(AL_KEY)==="1"; }catch(e){ return false; } }
function checkAlerts(){
  if(!alertsOn()) return;
  const f = follows(), since = state.alertSeen || "2000-01-01";
  const news = allFil().filter(x=>!x.futur && x.id && f.includes(x.id) && x.d > since);
  if(!news.length) return;
  const msg = news.length===1 ? t("Nouveau fait : {c}",{c:C[news[0].id].short}) : t("{n} nouveaux faits sur tes pays suivis",{n:news.length});
  let shown = false;
  try{ if(window.Notification && Notification.permission==="granted" && document.hidden){ new Notification("Sankofa", {body:msg, icon:"icons/icon-192.png"}); shown = true; } }catch(e){}
  if(!shown) toast(msg);
  state.alertSeen = news.map(x=>x.d).sort().pop(); save();
}
function addAlertsCard(){
  if($("#alertCard")) return; const top = $("#actuTop"); if(!top) return;
  const on = alertsOn(), n = follows().length;
  top.insertAdjacentHTML("beforebegin", `<div class="card alertcard" id="alertCard"><div><div class="eyebrow">${t("Alertes")}</div><b>${on?t("Les alertes sont activées."):t("Être prévenu quand un pays que tu suis change.")}</b>
    <p class="src">${n?t("Tu suis {n} pays.",{n}):t("Suis d'abord un pays depuis sa fiche.")} ${t("Sur un téléphone, l'alerte arrive en notification une fois le site installé ; sinon, elle s'affiche dans la page.")}</p></div>
    <label class="sw"><input type="checkbox" id="alertSw" ${on?"checked":""} aria-label="${t("Alertes")}"><span></span></label></div>`);
  $("#alertSw").onchange = async e=>{
    const v = e.target.checked; try{ localStorage.setItem(AL_KEY, v?"1":""); }catch(er){}
    if(v){ try{ if(window.Notification && Notification.permission==="default") await Notification.requestPermission(); }catch(er){} if(!state.alertSeen){ state.alertSeen = allFil().filter(x=>!x.futur).map(x=>x.d).sort().pop() || "2026-01-01"; save(); } toast(t("Alertes activées")); }
    $("#alertCard").remove(); addAlertsCard();
  };
}
setTimeout(checkAlerts, 3000);
document.addEventListener("visibilitychange", ()=>{ if(!document.hidden) checkAlerts(); });

