const SAT = [["Gaza","2023","2025","palestine"],["El-Geneina","2022","2024","soudan"],["Port-au-Prince","2021","2025","haiti"]];
const SAT_BY = {palestine:0, soudan:1, haiti:2};
let satI = 0;
(function(){ $("#methode").insertAdjacentHTML("beforebegin", `<section class="view" id="v-satellite"><div class="wrap sect" id="satelliteIn"></div></section>`); })();
function renderSatellite(){
  const s = SAT[satI];
  $("#satelliteIn").innerHTML = `<a class="back" href="#pays-${s[3]}">← ${t("Retour")}</a><div class="lhead"><div class="eyebrow">${t("Avant / après")}</div><h1>${t("Le même lieu, à quelques années d'écart.")}</h1><p class="dlede">${t("Fais glisser le curseur pour comparer deux images satellite du même endroit.")}</p></div>
    <div class="filters">${SAT.map((x,i)=>`<button class="filter" data-s="${i}" aria-pressed="${i===satI}">${esc(x[0])}</button>`).join("")}</div>
    <div class="satwrap" id="satW" role="slider" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50" tabindex="0" aria-label="${t("Avant / après")}"><canvas id="satA"></canvas><div class="satclip" id="satClip"><canvas id="satB"></canvas></div><div class="sathandle" id="satH"><i></i></div>
      <span class="satl l">${s[1]}</span><span class="satl r">${s[2]}</span></div>
    <div class="pwarn"><b>${t("Images en préparation.")}</b> ${t("Les images viendront du programme européen Copernicus (Sentinel-2), gratuites et créditées. Les évaluations de dégâts de l'ONU (UNOSAT) serviront de légende.")}</div>
    <a class="cta ghost" href="#pays-${s[3]}">${t("Ouvrir la fiche")}</a>`;
  document.querySelectorAll("[data-s]").forEach(b=>b.onclick=()=>{ satI = +b.dataset.s; renderSatellite(); });
  const W = $("#satW"), w = W.clientWidth, h = Math.round(w*.56);
  [["#satA",0],["#satB",1]].forEach(([sel,k])=>{ const cv = $(sel); cv.width = w*DPR; cv.height = h*DPR; cv.style.width = w+"px"; cv.style.height = h+"px"; const x = cv.getContext("2d"); x.scale(DPR,DPR);
    x.fillStyle = k ? "#3b3f45" : "#2d4a3a"; x.fillRect(0,0,w,h);
    let seed = 7+satI*13; const rnd = ()=>{ seed = (seed*9301+49297)%233280; return seed/233280; };
    for(let i=0;i<46;i++){ x.fillStyle = k ? "rgba(255,255,255,.07)" : "rgba(255,255,255,.12)"; x.fillRect(rnd()*w, rnd()*h, 20+rnd()*60, 14+rnd()*40); }
    x.strokeStyle = "rgba(255,255,255,.22)"; x.lineWidth = 1; for(let gx=0; gx<w; gx+=48){ x.beginPath(); x.moveTo(gx,0); x.lineTo(gx,h); x.stroke(); } for(let gy=0; gy<h; gy+=48){ x.beginPath(); x.moveTo(0,gy); x.lineTo(w,gy); x.stroke(); }
    x.fillStyle = "rgba(0,0,0,.55)"; x.fillRect(12, h-44, 290, 32); x.fillStyle = "#fff"; x.font = "600 13px system-ui, sans-serif"; x.fillText(t("Image {y} à venir · {p}",{y:s[k?2:1], p:s[0]}), 22, h-23); });
  W.style.height = h+"px";
  const set = p=>{ p = Math.max(0,Math.min(1,p)); $("#satClip").style.clipPath = `inset(0 0 0 ${p*100}%)`; $("#satH").style.left = p*100+"%"; W.setAttribute("aria-valuenow", Math.round(p*100)); W._p = p; };
  set(.5);
  let drag = false; const mv = e=>{ if(!drag) return; const r = W.getBoundingClientRect(); set((e.clientX-r.left)/r.width); };
  W.onpointerdown = e=>{ drag = true; W.setPointerCapture(e.pointerId); mv(e); }; W.onpointermove = mv; W.onpointerup = ()=>drag = false;
  W.onkeydown = e=>{ if(e.key==="ArrowLeft"){ set(W._p-.05); e.preventDefault(); } if(e.key==="ArrowRight"){ set(W._p+.05); e.preventDefault(); } };
}
