function countryAt(ev){
  const b = gc.getBoundingClientRect();
  const x = (ev.clientX-b.left)*(GW/b.width), y = (ev.clientY-b.top)*(GW/b.height);
  const ll = proj.invert([x,y]); if(!ll || d3.geoDistance(ll,[-rot[0],-rot[1]])>Math.PI/2) return null;
  for(const f of F110){ if(d3.geoContains(f,ll)) return f; }
  return null;
}
function countryName(f){ const n = NAMES[f.id]; return n ? n[LANG==="en"?1:0] : (f.properties && f.properties.name) || ""; }
let anyHover = null, anyRaf = 0;
gc.addEventListener("pointermove", ev=>{
  if(ev.buttons || moving || ev.pointerType==="touch" || anyRaf) return;
  anyRaf = requestAnimationFrame(()=>{
    anyRaf = 0;
    if(hover){ anyHover = null; tip.classList.remove("tipmini"); return; }            /* une fiche est déjà survolée : l'infobulle d'origine s'affiche */
    const f = countryAt(ev);
    if(!f){ if(anyHover){ anyHover = null; tip.classList.remove("show","tipmini"); } return; }
    anyHover = f.id;
    const has = C[f.id];
    tip.innerHTML = `<b>${esc(countryName(f))}</b><em>${has?t("Fiche disponible · touche pour l'ouvrir"):t("Pas encore de fiche")}</em>`;
    tip.classList.add("tipmini");
    gc.style.cursor = has ? "pointer" : "grab";
    const b = stage.getBoundingClientRect();
    let tx = ev.clientX-b.left+16, ty = ev.clientY-b.top+16; if(tx>b.width-220) tx -= 240;
    tip.style.left = tx+"px"; tip.style.top = ty+"px"; tip.classList.add("show");
  });
});
gc.addEventListener("pointerleave", ()=>{ anyHover = null; tip.classList.remove("tipmini"); });
gc.addEventListener("click", ev=>{ if(pick(ev)) return; const f = countryAt(ev); if(f && C[f.id]) location.hash = "pays-"+C[f.id].slug; });

/* Cachet de la cause sur la page d'identité */
const _idCardV13 = idCardHTML;
idCardHTML = function(p){
  const html = _idCardV13(p), cause = p.cause ? L(p.cause) : null;
  const yr = (p.since||"").split("/").pop() || "";
  const seal = `<div class="idseal" aria-hidden="true"><div>SANKOFA<b>${esc((cause?cause.name:t("Toutes les causes")).toUpperCase().slice(0,18))}</b>${esc(yr)}</div></div>`;
  return html.replace('<div class="idmrz">', seal+'<div class="idmrz">');
};

/* ================= v14 : mode « Tout » sur l'accueil, nouveau passeport ================= */
Object.assign(EN, {
  "Tout":"All","Toutes les lectures":"All readings","Chaque couleur est une lecture du monde. Le globe passe d'un peuple à l'autre ; choisis une lecture pour la suivre.":"Each colour is a reading of the world. The globe moves from one people to the next; pick a reading to follow it.",
  "En ce moment":"Right now","Ouvrir la fiche":"Open the page","Passeport":"Passport","Nom":"Name","Rang":"Rank","Niveau":"Level","Cause":"Cause","Pays de cœur":"Heart country","Délivré le":"Issued","Numéro":"Number","Escales":"Stops"
});

/* ---------- Mode « Tout » ---------- */
var MIX = true, SPOT = null, spotPrevLayer = null;
const _setLayerV14 = setLayer;
setLayer = function(id){
  if(id==="all"){ MIX = true; dirty = true; markSeg(); renderLayerCard(); nextSpot(true); return; }
  MIX = false; SPOT = null; dirty = true;
  _setLayerV14(id); markSeg();
};
function markSeg(){ document.querySelectorAll(".segbtn").forEach(b=>b.setAttribute("aria-pressed", MIX ? b.dataset.id==="all" : b.dataset.id===active)); }
const _renderSegV14 = renderSeg;
renderSeg = function(){
  _renderSegV14();
  $("#seg").insertAdjacentHTML("afterbegin", `<button class="segbtn segall" data-id="all" aria-pressed="${MIX}"><i></i>${t("Tout")}</button>`);
  document.querySelectorAll(".segbtn").forEach(b=>b.onclick=()=>setLayer(b.dataset.id));
  markSeg();
};
/* couleur de chaque pays en mode « Tout » : la couleur de sa crise principale */
var FILLC = {};
function mixCol(hex, k){ const key = TH.base+hex+k; return FILLC[key] || (FILLC[key] = d3.interpolateRgb(TH.base, hex)(k)); }
function fillFor(id){
  const c = C[id]; if(!c) return null;
  if(MIX){ const m = mainLayer(c); if(!m || !Object.keys(c.layers).length && !FEATURED.includes(id)) return null; return mixCol(m.hex, id===SPOT ? .92 : .5); }
  const lv = c.layers[active]; if(!lv) return null;
  return mixCol(L(active).hex, routesOn ? .12+lv*.07 : .35+lv*.2);
}
/* boîtes englobantes : on ne teste en détail que les pays dont la boîte contient le point */
var BBOX = new WeakMap();
function inBox(f, ll){
  let b = BBOX.get(f); if(!b){ b = d3.geoBounds(f); BBOX.set(f, b); }
  const [[x0,y0],[x1,y1]] = b, x = ll[0], y = ll[1];
  if(y<y0-.5 || y>y1+.5) return false;
  return x0<=x1 ? (x>=x0-.5 && x<=x1+.5) : (x>=x0-.5 || x<=x1+.5);
}
function pick(ev){
  const b = gc.getBoundingClientRect();
  const x = (ev.clientX-b.left)*(GW/b.width), y = (ev.clientY-b.top)*(GW/b.height);
  const ll = proj.invert([x,y]); if(!ll) return null;
  if(d3.geoDistance(ll,[-rot[0],-rot[1]])>Math.PI/2) return null;
  const ok = id=> MIX ? !!fillFor(id) : !!C[id].layers[active];
  for(const f of DATA_F){ if(ok(f.id) && inBox(f,ll) && d3.geoContains(zk<1.6 && typeof F110D!=='undefined' && F110D && F110D[f.id] || f, ll)) return f.id; }
  for(const id in C){ if(!featById[id] || !ok(id)) continue; const p = proj(centroid(id)); if(p && Math.hypot(p[0]-x,p[1]-y)<14) return id; }
  return null;
}
function nextSpot(now){
  const center = [-rot[0],-rot[1]];
  let cands = Object.keys(C).filter(id=>featById[id] && fillFor(id) && d3.geoDistance(centroid(id), center) < 1.15);
  if(!cands.length) cands = Object.keys(C).filter(id=>featById[id] && fillFor(id));
  const diff = cands.filter(id=>id!==SPOT && mainLayer(C[id]).id!==spotPrevLayer);
  const pool = diff.length ? diff : cands.filter(id=>id!==SPOT);
  SPOT = pool[Math.floor(Math.random()*pool.length)] || null; spotPrevLayer = SPOT ? mainLayer(C[SPOT]).id : null;
  SPOT_T = performance.now(); dirty = true; updSpotBox();
}
var SPOT_T = 0;
setInterval(()=>{ if(MIX && gVisible() && !document.hidden && !hover) nextSpot(); }, 1900);
function updSpotBox(){
  const box = $("#spotBox"); if(!box || !SPOT) return;
  const c = C[SPOT], m = mainLayer(c), f = c.figs.find(x=>x.l===m.id) || c.figs[0];
  box.style.setProperty("--sc", m.hex);
  box.innerHTML = `<div class="eyebrow">${t("En ce moment")} · <span>${m.name}</span></div><b>${esc(c.short)}</b><p>${esc(f.n ? f.n+" · "+f.d : f.t)}</p><a href="#pays-${c.slug}">${t("Ouvrir la fiche")} →</a>`;
  box.classList.remove("in"); void box.offsetWidth; box.classList.add("in");
}
const _renderLayerCardV14 = renderLayerCard;
renderLayerCard = function(){
  if(!MIX || routesOn) return _renderLayerCardV14.apply(this, arguments);
  const el = $("#layerCard"); el.classList.remove("rlpanel"); el.style.setProperty("--lc", "#C8962E");
  el.innerHTML = `<span class="lname">${t("Toutes les lectures")}</span>
    <p>${t("Chaque couleur est une lecture du monde. Le globe passe d'un peuple à l'autre ; choisis une lecture pour la suivre.")}</p>
    <div class="mixlist">${LAYERS.map(l=>`<button class="mixrow" data-id="${l.id}" style="--c:${l.hex}"><i></i><span>${l.name}</span><b>${l.big}</b></button>`).join("")}</div>
    <div class="spotbox" id="spotBox"></div>`;
  el.querySelectorAll(".mixrow").forEach(b=>b.onclick=()=>setLayer(b.dataset.id));
  updSpotBox();
};

/* ---------- Passeport : couverture ---------- */
const _renderPassV14 = renderPass;
renderPass = function(){
  _renderPassV14.apply(this, arguments);
  const head = $("#passHead"); if(!head) return;
  const cause = state.profile?.cause ? L(state.profile.cause) : null, LI = levelInfo();
  head.style.setProperty("--pc", cause ? cause.hex : "#C8962E");
  const av = head.querySelector(".phid .avsvg");
  if(av && !av.parentElement.classList.contains("avring")){ const w = document.createElement("span"); w.className = "avring"; w.style.setProperty("--p", Math.round(LI.into/LI.need*100)); av.replaceWith(w); w.appendChild(av); }
};

/* ---------- Passeport : page d'identité ---------- */
let sealN = 0;
function birdMarkup(){ const s = document.querySelector(".brand svg"); return s ? {vb:s.getAttribute("viewBox")||"0 0 64 64", html:s.innerHTML} : null; }
function sealSVG(text, color){
  const id = "sl"+(++sealN), b = birdMarkup();
  return `<svg class="idc-seal" viewBox="0 0 120 120" style="color:${color}" aria-hidden="true"><defs>
    <path id="${id}p" d="M60,60 m-43,0 a43,43 0 1,1 86,0 a43,43 0 1,1 -86,0"/>
    <filter id="${id}f" x="-10%" y="-10%" width="120%" height="120%"><feTurbulence type="fractalNoise" baseFrequency="1.1" numOctaves="2" seed="${sealN}" result="n"/><feDisplacementMap in="SourceGraphic" in2="n" scale="2.4" result="d"/><feComponentTransfer in="n" result="m"><feFuncA type="discrete" tableValues="1 1 1 0 1 1 1 1"/></feComponentTransfer><feComposite in="d" in2="m" operator="in"/></filter></defs>
    <g filter="url(#${id}f)"><circle cx="60" cy="60" r="56" fill="none" stroke="currentColor" stroke-width="2.6"/><circle cx="60" cy="60" r="51" fill="none" stroke="currentColor" stroke-width=".9"/><circle cx="60" cy="60" r="31" fill="none" stroke="currentColor" stroke-width="1.3"/>
    <text fill="currentColor" font-size="8.6" font-weight="700" letter-spacing="1.6" font-family="var(--body), system-ui, sans-serif"><textPath href="#${id}p">${esc(text)}</textPath></text>
    ${b?`<svg class="sbird" x="40" y="40" width="40" height="40" viewBox="${b.vb}">${b.html}</svg>`:""}
    <path d="M22 60h6M92 60h6" stroke="currentColor" stroke-width="1.4"/></g></svg>`;
}
idCardHTML = function(p){
  const cause = p.cause ? L(p.cause) : null, li = levelInfo(), col = cause ? cause.hex : "#C8962E";
  const yr = (p.since||"").split("/").pop() || String(new Date().getFullYear());
  const nm = (p.name||"VOYAGEUR").toUpperCase().normalize("NFD").replace(/[^A-Z]/g,"");
  const num = (p.num||"SK000000").replace(/[^A-Z0-9]/g,"");
  const mrz1 = ("P<SKF"+nm+"<<"+(LANG==="en"?"TRAVELLER":"VOYAGEUR")).padEnd(36,"<").slice(0,36);
  const mrz2 = (num+"<"+Object.keys(state.stamps).length+"SKF"+(p.since||"").replace(/\//g,"")+"<<"+li.l).padEnd(36,"<").slice(0,36);
  const b = birdMarkup();
  const seal = sealSVG(`SANKOFA · ${(cause?cause.name:t("Toutes les causes")).toUpperCase()} · ${yr} · `, col);
  const row = (k,v)=>`<div><dt>${t(k)}</dt><dd>${v}</dd></div>`;
  return `<div class="idcard idc" style="--c:${col}">
    <div class="idc-band"><span>${t("Passeport")} · Sankofa</span><span class="idc-code">SKF</span></div>
    <div class="idc-body">
      <div class="idc-photo">${avatarSVG(p,104)}</div>
      <dl class="idc-f">
        ${row("Nom", `<span class="idc-name">${esc(p.name||t("Voyageur"))}</span>`)}
        ${row("Rang", esc(title()))}
        ${row("Niveau", li.l)}
        ${row("Escales", Object.keys(state.stamps).length+" / "+FEATURED.length)}
        ${row("Cause", cause?esc(cause.name):t("Toutes les causes"))}
        ${p.heart && C[p.heart] ? row("Pays de cœur", esc(C[p.heart].short)) : row("Délivré le", esc(p.since||""))}
      </dl>
      ${seal}
    </div>
    <div class="idc-mrz"><span>${esc(mrz1).replace(/</g,"&lt;")}</span><span>${esc(mrz2).replace(/</g,"&lt;")}</span></div>
    <i class="idc-holo" aria-hidden="true"></i>
    ${b?`<svg class="idc-wm" viewBox="${b.vb}" aria-hidden="true">${b.html}</svg>`:""}
  </div>`;
};

