/* Carte « passeport » à partager : style clair, texte très lisible */
(function(){
  const _mk = makeCard;
  makeCard = async function(kind, id, extra){
    if(kind!=="id" || !state.profile) return _mk(kind, id, extra);
    const W=1080, H=1350, cv=document.createElement("canvas"); cv.width=W; cv.height=H; const x=cv.getContext("2d");
    try{ await document.fonts.ready; }catch(e){}
    const p=state.profile, en=LANG==="en", cause=p.cause?L(p.cause):null, col=cause?cause.hex:"#B8862B";
    const svgImg = async (svg)=>{ const im=new Image(); im.src="data:image/svg+xml;charset=utf-8,"+encodeURIComponent(svg.includes("xmlns=")?svg:svg.replace("<svg ",'<svg xmlns="http://www.w3.org/2000/svg" ')); await new Promise(r=>{im.onload=r;im.onerror=r;}); return im; };
    // fond
    x.fillStyle="#EFEDE6"; x.fillRect(0,0,W,H);
    const g=x.createRadialGradient(W*.8,120,40,W*.8,120,700); g.addColorStop(0,col+"33"); g.addColorStop(1,col+"00"); x.fillStyle=g; x.fillRect(0,0,W,H);
    drawMark(x,72,64,64,"#121315","#C8962E","#EFEDE6");
    x.fillStyle="#121315"; x.font="400 50px 'Instrument Serif', serif"; x.textAlign="left"; x.fillText("Sankofa",152,112);
    // carte
    const cx=64, cy=200, cw=W-128, ch=820, r=40;
    x.save(); x.shadowColor="rgba(18,19,21,.18)"; x.shadowBlur=60; x.shadowOffsetY=24;
    x.beginPath(); x.roundRect(cx,cy,cw,ch,r); x.fillStyle="#FBFAF6"; x.fill(); x.restore();
    x.save(); x.beginPath(); x.roundRect(cx,cy,cw,ch,r); x.clip();
    x.fillStyle=col; x.fillRect(cx,cy,cw,92);
    x.fillStyle="#fff"; x.font="600 28px 'Geist Mono', monospace"; x.textAlign="left";
    x.fillText((en?"PASSPORT":"PASSEPORT")+" · SANKOFA", cx+44, cy+58); x.textAlign="right"; x.fillText("SKF", cx+cw-44, cy+58);
    // photo
    const av = await svgImg(avatarSVG(p,300));
    x.save(); x.beginPath(); x.roundRect(cx+44,cy+136,260,300,28); x.fillStyle="#E8E5DC"; x.fill(); x.restore(); x.drawImage(av,cx+64,cy+176,220,220);
    // champs
    const fx=cx+352; let fy=cy+160;
    const field=(lab,val,big)=>{ x.textAlign="left"; x.fillStyle="#6A6D72"; x.font="500 22px 'Geist Mono', monospace"; x.fillText(lab.toUpperCase(),fx,fy);
      x.fillStyle="#121315"; x.font=`400 ${big?78:46}px 'Instrument Serif', serif`; x.fillText(val,fx,fy+(big?72:50)); fy += big?118:92; };
    field(t("Nom"), p.name||t("Voyageur"), true);
    field(t("Rang"), title()+" · "+t("Niveau")+" "+level());
    const ns=Object.keys(state.stamps).length;
    field(t("Escales"), ns+" / "+FEATURED.length);
    if(cause) field(t("Cause"), cause.name);
    if(p.heart && C[p.heart]) field(t("Pays de cœur"), C[p.heart].short);
    // tampon
    try{ const seal = await svgImg(sealSVG("SANKOFA · "+(p.num||"SKF"), col).replace('class="idc-seal"','').replace(/currentColor/g,col).replace(/filter="[^"]*"/g,""));
      x.save(); x.globalAlpha=.8; x.translate(cx+174, cy+ch-270); x.rotate(-.18); x.drawImage(seal,-105,-105,210,210); x.restore(); }catch(e){}
    // MRZ
    x.fillStyle="#E9E6DD"; x.fillRect(cx,cy+ch-150,cw,150);
    const nm=(p.name||"VOYAGEUR").toUpperCase().normalize("NFD").replace(/[^A-Z]/g,"").slice(0,14);
    const l1=("P<SKF"+nm+"<<"+(en?"TRAVELLER":"VOYAGEUR")).padEnd(40,"<").slice(0,40), l2=((p.num||"SK000000")+"<"+level()+"SKF"+ns).padEnd(40,"<").slice(0,40);
    x.fillStyle="#3A3D42"; x.font="500 30px 'Geist Mono', monospace"; x.textAlign="left"; x.fillText(l1,cx+44,cy+ch-90); x.fillText(l2,cx+44,cy+ch-44);
    x.restore();
    // invitation
    x.fillStyle="#121315"; x.font="400 54px 'Instrument Serif', serif"; x.textAlign="center";
    wrapText(x,t("Rejoins-moi sur Sankofa, l'atlas des peuples éprouvés."),W/2,1130,900,64);
    x.fillStyle="#121315"; x.fillRect(0,H-36,W,36);
    return cv;
  };
})();

countryAt = function(ev){
  const b = gc.getBoundingClientRect();
  const x = (ev.clientX-b.left)*(GW/b.width), y = (ev.clientY-b.top)*(GW/b.height);
  const ll = proj.invert([x,y]); if(!ll || d3.geoDistance(ll,[-rot[0],-rot[1]])>Math.PI/2) return null;
  for(const f of F110){ if(inBox(f,ll) && d3.geoContains(f,ll)) return f; }
  return null;
};

/* Intro plus courte : un double coup de bec, l'œuf s'illumine, le site s'ouvre depuis l'œuf */
function intro(){
  let seen=false; try{ seen = sessionStorage.getItem("skf-intro2"); sessionStorage.setItem("skf-intro2","1"); }catch(e){}
  const el=$("#splash"); if(!el) return;
  if(seen || reduce){ el.remove(); document.documentElement.classList.add("nosplash"); return; }
  window.scrollTo(0,0);
  el.classList.add("play");
  let done=false; const end=()=>{ if(done) return; done=true;
    const r=el.querySelector(".segg").getBoundingClientRect(); el.style.setProperty("--x",(r.left+r.width/2)+"px"); el.style.setProperty("--y",(r.top+r.height/2)+"px");
    requestAnimationFrame(()=>el.classList.add("sopen")); setTimeout(()=>el.remove(),800); };
  el.onclick=end; setTimeout(end,1250);
}

/* Intro v2 : à chaque chargement (pas au clic sur le logo), plus calme, l'œuf mangé en trois coups de bec */
function intro(){
  const el=$("#splash"); if(!el) return;
  if(reduce || document.documentElement.classList.contains("nosplash")){ el.remove(); document.documentElement.classList.add("nosplash"); return; }
  window.scrollTo(0,0);
  // miettes : trois petites salves, une par coup de bec
  const svg = el.querySelector(".sbird"), egg = el.querySelector(".segg");
  if(svg && egg && !svg.querySelector(".scrumb")){
    const hits = [0.65+1.5*0.11, 0.65+1.5*0.44, 0.65+1.5*0.77];
    const dirs = [[-2.6,-1.6],[-1.2,2.2],[1.8,-2.2],[2.4,1.4],[-2.8,0.6],[0.4,-2.8]];
    let k = 0, html = "";
    hits.forEach((t,h)=>{ for(let j=0;j<3;j++){ const d = dirs[(k++)%dirs.length]; const r = (0.42 - h*0.08).toFixed(2);
      html += `<circle class="scrumb" cx="11.2" cy="14.4" r="${r}" fill="#C8962E" style="--dx:${d[0]}px;--dy:${d[1]}px;animation-delay:${t.toFixed(2)}s"/>`; } });
    egg.insertAdjacentHTML("afterend", html);
  }
  el.classList.add("play");
  let done=false; const end=()=>{ if(done) return; done=true;
    const r=egg.getBoundingClientRect(); el.style.setProperty("--x",(r.left+r.width/2)+"px"); el.style.setProperty("--y",(r.top+r.height/2)+"px");
    requestAnimationFrame(()=>el.classList.add("sopen")); setTimeout(()=>el.remove(),1100); };
  el.onclick=end; setTimeout(end,2450);
}

