/* ---------- Extras de lancement : tri d'Explorer, défi entre amis, point « non sauvegardé »,
   proposition d'installer l'appli (comptes), espace enseignant ---------- */
(function(){
  const SITE_URL = "https://sankofa-atlas.org";
  const ls = { get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }, set(k, v){ try{ localStorage.setItem(k, v); }catch(e){} } };
  const ss = { get(k){ try{ return sessionStorage.getItem(k); }catch(e){ return null; } }, set(k, v){ try{ sessionStorage.setItem(k, v); }catch(e){} } };
  const qp = (()=>{ try{ return new URLSearchParams(location.search); }catch(e){ return new URLSearchParams(""); } })();

  /* =========================================================
     1. Explorer : trier
     ========================================================= */
  const CONT = {
    af: ["120","180","231","232","384","466","478","508","566","706","728","729","732","854"],
    mo: ["275","364","368","414","422","682","760","784","792","887"],
    as: ["104","156","408","586","608","762","764","004","050"],
    eu: ["643","804"],
    am: ["170","332","484","558","862","076"],
    oc: ["360"]
  };
  const CONT_NAME = {af:"Afrique", mo:"Moyen-Orient", as:"Asie", eu:"Europe", am:"Amériques", oc:"Océanie"};
  const CONT_OF = {}; Object.keys(CONT).forEach(k=>CONT[k].forEach(id=>CONT_OF[id] = k));
  const contOf = id => CONT_OF[id] || "zz";
  const nCrises = id => Object.keys((C[id] && C[id].layers) || {}).length;
  let exSort = ls.get("skf-exsort") || "une";
  if(typeof renderExplorer === "function"){
    const _re = renderExplorer;
    renderExplorer = function(){
      _re.apply(this, arguments);
      const f = $("#filters"), grid = $("#exGrid"); if(!f || !grid) return;
      let bar = $("#exSort");
      if(!bar){
        f.insertAdjacentHTML("beforebegin", `<div class="exsort" id="exSort" role="group" aria-label="${t("Trier")}"><span class="exlab">${t("Trier")}</span>
          ${[["une","À la une"],["az","A à Z"],["cont","Par continent"],["crises","Par nombre de crises"]].map(([k, l])=>`<button type="button" data-s="${k}">${t(l)}</button>`).join("")}</div>`);
        bar = $("#exSort");
        bar.onclick = e=>{ const b = e.target.closest("button[data-s]"); if(!b) return; exSort = b.dataset.s; ls.set("skf-exsort", exSort); renderExplorer(); };
      }
      bar.querySelectorAll("button").forEach(b=>b.setAttribute("aria-pressed", b.dataset.s === exSort));
      if(exSort === "une") return;
      const ids = Object.keys(C).filter(id=>exFilter === "all" || C[id].layers[exFilter]);
      const az = (a, b)=>C[a].short.localeCompare(C[b].short, LANG);
      let html;
      if(exSort === "az") html = ids.sort(az).map(pcard).join("");
      else if(exSort === "crises") html = ids.sort((a, b)=>nCrises(b) - nCrises(a) || az(a, b)).map(pcard).join("");
      else {
        const order = ["af","mo","as","eu","am","oc","zz"];
        html = order.map(k=>{ const g = ids.filter(id=>contOf(id) === k).sort(az); if(!g.length) return "";
          return `<h3 class="exgroup">${esc(t(CONT_NAME[k] || "Autres"))}<span>${g.length}</span></h3>` + g.map(pcard).join(""); }).join("");
      }
      grid.innerHTML = html; hydrate(grid);
    };
  }

  /* =========================================================
     2. Défier un ami (discret, sous le résultat d'un quiz)
     ========================================================= */
  (function(){ const d = qp.get("defi"); if(!d) return;
    const m = d.match(/^([a-z0-9-]+)\.([0-3])\.(\d{1,2})\.(\d{1,2})$/); if(!m) return;
    ss.set("skf-defi", JSON.stringify({slug:m[1], lv:+m[2], s:+m[3], n:+m[4], name:(qp.get("n") || "").slice(0, 24)})); })();
  const defiIn = ()=>{ try{ return JSON.parse(ss.get("skf-defi") || "null"); }catch(e){ return null; } };
  const lvName = lv => t((LEVELS[lv] || {}).name || "");
  if(typeof renderQuizView === "function"){
    const _rqv = renderQuizView;
    renderQuizView = function(id){
      _rqv.apply(this, arguments);
      const d = defiIn(); if(!d || !C[id] || C[id].slug !== d.slug || $("#defiBan")) return;
      const head = $("#quizIn .qhead"); if(!head) return;
      head.insertAdjacentHTML("afterend", `<div class="defiban" id="defiBan"><span>${t("{n} te défie : {s} sur {t} au niveau {l}. À toi de faire mieux.", {n:esc(d.name || t("Un ami")), s:d.s, t:d.n, l:esc(lvName(d.lv))})}</span>
        ${d.lv > 0 && (state.stamps[id]?.r || 0) < d.lv ? "" : `<button class="linkbtn" id="defiGo">${t("Relever le défi")}</button>`}</div>`);
      const g = $("#defiGo"); if(g) g.onclick = ()=>{ renderLevels(id, d.lv); $("#quizBox").scrollIntoView({behavior:"smooth", block:"start"}); };
    };
  }
  if(typeof runQuiz === "function"){
    const _rq = runQuiz;
    runQuiz = function(box, qs0, opt){
      opt = opt || {};
      if(opt.id && opt.lv != null){
        const prev = opt.onEnd;
        opt = Object.assign({}, opt, {onEnd: score=>{ if(prev) prev(score); setTimeout(()=>defiAfter(box, opt, score), 0); }});
      }
      return _rq.call(this, box, qs0, opt);
    };
  }
  async function defiAfter(box, opt, score){
    const r = box && box.querySelector(".result"); if(!r || r.querySelector(".defi")) return;
    const c = C[opt.id], tot = (LEVELS[opt.lv] || {}).n || 4, d = defiIn();
    let vs = "";
    if(d && d.slug === c.slug && d.lv === opt.lv){
      const who = esc(d.name || t("Ton ami"));
      vs = score > d.s ? t("Tu as battu {n} : {a} contre {b}.", {n:who, a:score, b:d.s}) : score === d.s ? t("Égalité avec {n} : {a} partout.", {n:who, a:score}) : t("{n} garde l'avantage : {b} contre {a}.", {n:who, a:score, b:d.s});
    }
    r.insertAdjacentHTML("beforeend", `<p class="defi">${vs ? `<span class="defivs">${vs}</span>` : ""}<button class="linkbtn" id="defiBtn">${t("Défier un ami sur ce quiz")}</button></p>`);
    r.querySelector("#defiBtn").onclick = async ()=>{
      let code = null; try{ const L = window.skfLaunch ? await window.skfLaunch() : null; code = L && L.me && L.me.code; }catch(e){}
      const name = state.profile && state.profile.name ? state.profile.name.slice(0, 20) : "";
      const link = SITE_URL + "/" + c.slug + "/?defi=" + c.slug + "." + opt.lv + "." + score + "." + tot + (name ? "&n=" + encodeURIComponent(name) : "") + (code ? "&p=" + code : "") + "#quiz-" + c.slug;
      const text = t("J'ai eu {s} sur {n} au quiz {c}, niveau {l}, sur Sankofa. Tu fais mieux ?", {s:score, n:tot, c:c.short, l:lvName(opt.lv)});
      if(window.skfEvent) skfEvent("share", "defi:" + c.slug);
      if(navigator.share){ try{ await navigator.share({title:"Sankofa", text, url:link}); return; }catch(e){ if(e && e.name === "AbortError") return; } }
      try{ await navigator.clipboard.writeText(text + " " + link); toast(t("Lien du défi copié. Envoie-le à un ami.")); }
      catch(e){ prompt(t("Copie le lien du défi :"), link); }
    };
  }

  /* =========================================================
     3. Point « non sauvegardé » sur l'avatar, tant qu'il n'y a pas de compte
     ========================================================= */
  if(typeof renderAccount === "function"){
    const _ra = renderAccount;
    renderAccount = function(){
      _ra.apply(this, arguments);
      const b = $("#acctBtn"); if(!b) return;
      const unsaved = !state.account && (Object.keys(state.stamps || {}).length > 0 || state.xp > 0 || !!state.profile);
      b.classList.toggle("unsaved", unsaved);
      const dot = b.querySelector(".dot"); if(dot) dot.style.display = state.account ? "" : "none";
      if(unsaved){ b.setAttribute("title", t("Progression non sauvegardée : crée un compte pour la garder")); if(!b.querySelector(".udot")) b.insertAdjacentHTML("beforeend", `<i class="udot" aria-hidden="true"></i>`); }
      else { b.removeAttribute("title"); const u = b.querySelector(".udot"); if(u) u.remove(); }
    };
  }

  /* =========================================================
     4. Proposer d'installer l'appli, seulement aux personnes qui ont un compte
     ========================================================= */
  function maybeInstall(){
    if(!state.account || $("#instNudge")) return;
    if(typeof isStandalone === "function" && isStandalone()) return;
    if(typeof isFramed === "function" && isFramed()) return;
    if(ls.get("skf-inst-done")) return;
    const later = +(ls.get("skf-inst-later") || 0); if(Date.now() - later < 7 * 864e5) return;
    if(document.querySelector("#modal.show, #sheet.show, #lvlup.show") || document.body.classList.contains("focus")) return;
    document.body.insertAdjacentHTML("beforeend", `<div class="instnudge" id="instNudge" role="dialog" aria-label="${t("Installer Sankofa")}">
      <div class="inico"><svg viewBox="0 0 32 32"><path d="M4.5 17.5 1.8 13.2l4.4 2.1z" fill="#F2F3EF"/><ellipse cx="14.5" cy="20" rx="9.5" ry="6.2" transform="rotate(-12 14.5 20)" fill="#F2F3EF"/><path d="M21.5 17.2C25.8 11 21 4.6 15.4 7.4" fill="none" stroke="#F2F3EF" stroke-width="3.4" stroke-linecap="round"/><circle cx="14.6" cy="8.6" r="3.3" fill="#F2F3EF"/><path d="M12.2 10.3 10.3 13.4l3.4-1.6z" fill="#F2F3EF"/><ellipse cx="11.6" cy="14.6" rx="2.5" ry="1.9" fill="#C8962E"/><circle cx="15.6" cy="7.9" r=".9" fill="#121315"/><path d="M12.5 25.5v4M17 25v4.5" stroke="#F2F3EF" stroke-width="1.6" stroke-linecap="round"/></svg></div>
      <div class="intx"><b>${t("Ajoute Sankofa à ton écran d'accueil")}</b><span>${t("Ton passeport à portée de main, en un geste.")}</span></div>
      <div class="inbtns"><button class="cta" id="instGo">${t("Comment faire")}</button><button class="linkbtn" id="instNo">${t("Plus tard")}</button></div></div>`);
    const el = $("#instNudge"); requestAnimationFrame(()=>el.classList.add("show"));
    const close = ()=>{ el.classList.remove("show"); setTimeout(()=>el.remove(), 300); };
    $("#instGo").onclick = ()=>{ ls.set("skf-inst-done", "1"); close(); openInstall(); };
    $("#instNo").onclick = ()=>{ ls.set("skf-inst-later", String(Date.now())); close(); };
  }
  addEventListener("appinstalled", ()=>ls.set("skf-inst-done", "1"));
  setTimeout(maybeInstall, 25000);

  /* =========================================================
     5. Espace enseignant (lien discret en bas de page)
     ========================================================= */
  (function(){ const c = qp.get("classe"); if(c && /^[A-Za-z0-9]{6}$/.test(c)) ss.set("skf-classe", c.toUpperCase()); })();
  function addLinks(){
    const fi = document.querySelector(".flinks .finstall");
    if(fi && !document.querySelector(".flinks .fclass")) fi.insertAdjacentHTML("afterend", `<a href="#classe" class="fclass">${t("Espace enseignant")}</a>`);
    const si = document.querySelector(".setlinks .setinstall");
    if(si && !document.querySelector(".setlinks .setclass")) si.insertAdjacentHTML("afterend", `<a href="#classe" class="setclass">${t("Espace enseignant")}</a>`);
  }
  addLinks(); new MutationObserver(addLinks).observe(document.body, {childList:true, subtree:true});
  document.addEventListener("click", e=>{ const a = e.target.closest('a[href="#classe"]'); if(a){ e.preventDefault(); try{ closeSettings(); }catch(x){} openClasses(); } });

  const ERR = {"compte requis":"Il faut un compte pour cela.", "code inconnu":"Ce code ne correspond à aucune classe.", "classe pleine":"Cette classe est complète.", "nom invalide":"Donne un nom à ta classe (2 à 60 caractères).", "trop de classes":"Tu as déjà 20 classes."};
  const errText = e=>{ const m = String((e && e.message) || ""); const k = Object.keys(ERR).find(x=>m.includes(x)); return t(k ? ERR[k] : "Impossible pour le moment. Réessaie plus tard."); };
  const ago = d=>{ if(!d) return t("jamais"); const s = (Date.now() - new Date(d).getTime()) / 1000; if(s < 3600) return t("à l'instant"); if(s < 86400) return t("aujourd'hui"); const n = Math.floor(s / 86400); return n === 1 ? t("hier") : t("il y a {n} jours", {n}); };
  let CL = {data:null, open:{}};
  async function openClasses(){
    const m = $("#modal");
    m.innerHTML = `<div class="mbox clbox" role="dialog" aria-modal="true" aria-labelledby="clT"><button class="mclose" aria-label="${t("Fermer")}">×</button><div id="clIn"><p class="clwait">${t("Un instant…")}</p></div></div>`;
    m.classList.add("show");
    const close = ()=>m.classList.remove("show");
    m.querySelector(".mclose").onclick = close; m.onclick = e=>{ if(e.target === m) close(); };
    if(state.account){ try{ CL.data = await SB.rpc("sankofa_class_mine"); }catch(e){ CL.data = {teach:[], joined:[], err:true}; } }
    paintClasses();
  }
  function paintClasses(){
    const box = $("#clIn"); if(!box) return;
    const pre = ss.get("skf-classe") || "";
    const head = `<div class="eyebrow">${t("Espace enseignant")}</div><h2 id="clT">${t("Ta classe sur Sankofa.")}</h2>
      <p class="cllead">${t("Crée une classe, donne le code à tes élèves, et vois ce que chacun a appris : tampons, points, dernière activité. Les élèves ne voient jamais les résultats des autres.")}</p>`;
    if(!state.account){
      box.innerHTML = head + `<div class="clcard"><p>${t("Pour créer une classe ou en rejoindre une, il faut un compte. Le quiz en direct, lui, se joue sans compte.")}</p>
        <div class="clrow"><button class="cta" id="clUp">${t("Créer un compte")}</button><button class="cta ghost" id="clIn2">${t("Se connecter")}</button></div></div>`;
      const go = tab=>{ $("#modal").classList.remove("show"); authTab = tab; openSheet("account"); };
      $("#clUp").onclick = ()=>go("up"); $("#clIn2").onclick = ()=>go("in");
      if(window.skfLiveHook) skfLiveHook(box, false); return;
    }
    const d = CL.data || {teach:[], joined:[]};
    const joined = (d.joined || []).map(c=>`<li><b>${esc(c.name)}</b><span class="mono">${esc(c.code)}</span><button class="linkbtn" data-leave="${esc(c.code)}">${t("Quitter")}</button></li>`).join("");
    const teach = (d.teach || []).map(c=>{
      const st = c.students || [], open = !!CL.open[c.code];
      const link = SITE_URL + "/?classe=" + c.code;
      return `<div class="clclass"><button class="clhead" data-tog="${esc(c.code)}" aria-expanded="${open}"><span><b>${esc(c.name)}</b><em>${st.length} ${st.length > 1 ? t("élèves") : t("élève")}</em></span><span class="clcode mono">${esc(c.code)}</span></button>
        ${open ? `<div class="clbody">
          <div class="clshare"><span>${t("Code à donner aux élèves")}</span><b class="mono">${esc(c.code)}</b><button class="cta ghost" data-copy="${esc(link)}">${t("Copier le lien")}</button><button class="cta ghost" data-qr="${esc(c.code)}" data-qrname="${esc(c.name)}">${t("Afficher le QR code")}</button></div>
          ${st.length ? `<ol class="clst">${st.map(s=>{ const n = Object.keys(s.stamps || {}).length; return `<li>${avatarSVG({fg:s.fg, bg:s.bg, egg:s.egg}, 28)}<span class="cln">${esc(s.name)}</span><span class="cls">${n} ${n > 1 ? t("tampons") : t("tampon")} · ${s.xp} XP</span><span class="cla">${esc(ago(s.last))}</span><button class="clx" data-rm="${esc(c.code)}|${esc(s.uid)}" aria-label="${t("Retirer de la classe")}" title="${t("Retirer de la classe")}">×</button></li>`; }).join("")}</ol>
            <p class="clsmall">${t("Pays tamponnés par la classe :")} ${esc(classStamps(st))}</p>`
          : `<p class="clsmall">${t("Personne pour l'instant. Donne le code ou le lien à tes élèves : ils le saisissent dans « Espace enseignant », en bas du site.")}</p>`}
          <button class="linkbtn cldel" data-del="${esc(c.code)}">${t("Supprimer cette classe")}</button></div>` : ""}</div>`;
    }).join("");
    box.innerHTML = head + (d.err ? `<p class="ferr show">${t("Impossible de charger tes classes pour le moment.")}</p>` : "") +
      `<div class="clcard"><div class="cltitle">${t("Rejoindre une classe")}</div><p class="clsmall">${t("Ton enseignant t'a donné un code à 6 caractères.")}</p>
        <form class="clrow" id="clJoin"><input id="clCode" class="clinput mono" maxlength="6" placeholder="K7P2QX" value="${esc(pre)}" autocomplete="off" autocapitalize="characters"><button class="cta" type="submit">${t("Rejoindre")}</button></form>
        ${joined ? `<ul class="cljoined">${joined}</ul>` : ""}</div>
      <div class="clcard"><div class="cltitle">${t("Mes classes")}</div>${teach || `<p class="clsmall">${t("Tu n'as pas encore de classe.")}</p>`}
        <form class="clrow" id="clNew"><input id="clName" class="clinput" maxlength="60" placeholder="${t("Ex. 3e B · Histoire-géo")}"><button class="cta ghost" type="submit">${t("Créer une classe")}</button></form></div>
      <p class="ferr" id="clErr" role="alert"></p>`;
    if(window.skfLiveHook) skfLiveHook(box, true);
    box.querySelectorAll("[data-qr]").forEach(b=>b.onclick = ()=>{ if(window.skfQR) skfQR(SITE_URL + "/?classe=" + b.dataset.qr, b.dataset.qr, b.dataset.qrname); });
    const err = m=>{ const e = $("#clErr"); e.textContent = m; e.classList.toggle("show", !!m); };
    const reload = async ()=>{ try{ CL.data = await SB.rpc("sankofa_class_mine"); }catch(e){} paintClasses(); };
    $("#clJoin").onsubmit = async e=>{ e.preventDefault(); const code = $("#clCode").value.trim().toUpperCase(); if(code.length !== 6) return err(t("Le code fait 6 caractères."));
      try{ const r = await SB.rpc("sankofa_class_join", {code}); ss.set("skf-classe", ""); toast(t("Tu as rejoint la classe « {n} ».", {n:r.name})); if(window.skfEvent) skfEvent("class", "join"); await reload(); }catch(x){ err(errText(x)); } };
    $("#clNew").onsubmit = async e=>{ e.preventDefault(); const name = $("#clName").value.trim(); if(name.length < 2) return err(t("Donne un nom à ta classe (2 à 60 caractères)."));
      try{ const r = await SB.rpc("sankofa_class_create", {name}); CL.open[r.code] = true; if(window.skfEvent) skfEvent("class", "create"); await reload(); }catch(x){ err(errText(x)); } };
    box.querySelectorAll("[data-tog]").forEach(b=>b.onclick = ()=>{ CL.open[b.dataset.tog] = !CL.open[b.dataset.tog]; paintClasses(); });
    box.querySelectorAll("[data-copy]").forEach(b=>b.onclick = async ()=>{ try{ await navigator.clipboard.writeText(b.dataset.copy); toast(t("Lien copié.")); }catch(e){ prompt(t("Copie le lien :"), b.dataset.copy); } });
    box.querySelectorAll("[data-leave]").forEach(b=>b.onclick = async ()=>{ if(!confirm(t("Quitter cette classe ?"))) return; try{ await SB.rpc("sankofa_class_leave", {code:b.dataset.leave}); await reload(); }catch(x){ err(errText(x)); } });
    box.querySelectorAll("[data-rm]").forEach(b=>b.onclick = async ()=>{ const [code, who] = b.dataset.rm.split("|"); if(!confirm(t("Retirer cet élève de la classe ?"))) return; try{ await SB.rpc("sankofa_class_leave", {code, who}); await reload(); }catch(x){ err(errText(x)); } });
    box.querySelectorAll("[data-del]").forEach(b=>b.onclick = async ()=>{ if(!confirm(t("Supprimer cette classe ? Les élèves en seront retirés."))) return; try{ await SB.rpc("sankofa_class_delete", {code:b.dataset.del}); await reload(); }catch(x){ err(errText(x)); } });
  }
  function classStamps(st){
    const cnt = {}; st.forEach(s=>Object.keys(s.stamps || {}).forEach(id=>cnt[id] = (cnt[id] || 0) + 1));
    const l = Object.entries(cnt).sort((a, b)=>b[1] - a[1]).map(([id, n])=>(C[id] ? C[id].short : id) + " (" + n + ")");
    return l.length ? l.join(", ") : t("aucun pour l'instant");
  }
  /* Lien d'invitation d'une classe : ouvrir l'espace une fois connecté */
  setTimeout(()=>{ if(ss.get("skf-classe")){ if(state.account) openClasses(); else toast(t("Crée un compte pour rejoindre la classe de ton enseignant, puis ouvre « Espace enseignant » en bas du site.")); } }, 3500);
})();

