/* ---------- Notifications sur le téléphone : actualités, nouveaux pays, votes ---------- */
(function(){
  const PUB = "BKOkazH4YpzieifcsAWuNSqNfntEVRlkSLzgmMFPSxjKD8p_rTCLT0b5W7R8vVafeeCYkOv3OvEZzpWD6h56EQY";
  const TOPICS = [["actu","Actualités","Un résumé par semaine"],["pays","Nouveaux pays","Quand un pays rejoint l'atlas"],["vote","Votes","Ouverture du vote et résultat"]];
  const ls = { get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } }, set(k, v){ try{ localStorage.setItem(k, v); }catch(e){} } };
  const supported = ()=>("serviceWorker" in navigator) && ("PushManager" in window) && ("Notification" in window);
  const isIOS = ()=>/iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  const isApp = ()=>{ try{ return matchMedia("(display-mode: standalone)").matches || navigator.standalone === true; }catch(e){ return false; } };
  const topics = ()=>{ try{ const a = JSON.parse(ls.get("skf-push-topics") || "null"); return Array.isArray(a) ? a : ["actu","pays","vote"]; }catch(e){ return ["actu","pays","vote"]; } };
  const b64 = s=>{ const p = "=".repeat((4 - s.length % 4) % 4), r = atob((s + p).replace(/-/g, "+").replace(/_/g, "/")); return Uint8Array.from(r, c=>c.charCodeAt(0)); };
  const key = (sub, k)=>{ const b = sub.getKey(k); return btoa(String.fromCharCode.apply(null, new Uint8Array(b))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""); };
  async function current(){ if(!supported()) return null; try{ const reg = await navigator.serviceWorker.getRegistration(); return reg ? await reg.pushManager.getSubscription() : null; }catch(e){ return null; } }
  async function save(sub){ await SB.rpc("push_subscribe", {endpoint:sub.endpoint, p256dh:key(sub, "p256dh"), auth:key(sub, "auth"), lang:LANG === "en" ? "en" : "fr", topics:topics()}); }
  async function enable(){
    const perm = await Notification.requestPermission();
    if(perm !== "granted") throw new Error("refus");
    const reg = await navigator.serviceWorker.ready;
    const sub = (await reg.pushManager.getSubscription()) || await reg.pushManager.subscribe({userVisibleOnly:true, applicationServerKey:b64(PUB)});
    await save(sub); ls.set("skf-push", "1");
    try{ await SB.rpc("push_test", {endpoint:sub.endpoint}); }catch(e){}
    if(window.skfEvent) skfEvent("push", "on");
  }
  async function disable(){
    const sub = await current();
    if(sub){ try{ await SB.rpc("push_unsubscribe", {endpoint:sub.endpoint}); }catch(e){} try{ await sub.unsubscribe(); }catch(e){} }
    ls.set("skf-push", "0"); if(window.skfEvent) skfEvent("push", "off");
  }
  /* si la langue ou le compte change, on remet l'abonnement à jour une fois par jour */
  setTimeout(async ()=>{ if(ls.get("skf-push") !== "1") return; const day = new Date().toISOString().slice(0, 10); if(ls.get("skf-push-sync") === day) return;
    const sub = await current(); if(sub){ try{ await save(sub); ls.set("skf-push-sync", day); }catch(e){} } else ls.set("skf-push", "0"); }, 6000);

  async function row(){
    const p = document.getElementById("setPop"); if(!p) return;
    const anchor = p.querySelector(".seticon") || p.querySelector(".setlinks");
    if(!anchor || p.querySelector(".setpush")) return;
    anchor.insertAdjacentHTML("beforebegin", `<div class="setrow setpush"><span class="eyebrow">${t("Notifications")}</span><div id="pushIn"></div></div>`);
    paint();
  }
  async function paint(msg){
    const box = document.getElementById("pushIn"); if(!box) return;
    if(!supported()){
      box.innerHTML = `<p class="sethint">${isIOS() && !isApp() ? t("Sur iPhone, ajoute d'abord Sankofa à ton écran d'accueil (bouton Partager, puis « Sur l'écran d'accueil »). Ouvre ensuite l'application et reviens ici.") : t("Ton navigateur ne permet pas les notifications.")}</p>`; return; }
    const sub = await current(), on = !!sub && Notification.permission === "granted", tp = topics();
    if(Notification.permission === "denied"){ box.innerHTML = `<p class="sethint">${t("Les notifications sont bloquées pour Sankofa. Autorise-les dans les réglages de ton téléphone ou de ton navigateur, puis reviens ici.")}</p>`; return; }
    box.innerHTML = `<button type="button" class="pushbtn" id="pushT" aria-pressed="${on}"><span>${on ? t("Notifications activées") : t("Activer les notifications")}</span><i></i></button>
      ${on ? `<div class="pushtopics">${TOPICS.map(([k, n, d])=>`<label><input type="checkbox" data-tp="${k}" ${tp.includes(k) ? "checked" : ""}><span><b>${t(n)}</b><em>${t(d)}</em></span></label>`).join("")}</div>` : `<p class="sethint">${t("Un résumé de l'actualité par semaine, les nouveaux pays et les votes. Jamais de publicité.")}</p>`}
      ${msg ? `<p class="sethint pushmsg">${esc(msg)}</p>` : ""}`;
    document.getElementById("pushT").onclick = async e=>{ e.stopPropagation(); const b = e.currentTarget; b.disabled = true;
      try{ if(on){ await disable(); paint(t("Notifications désactivées.")); } else { await enable(); paint(t("C'est activé. Tu vas recevoir une notification d'essai.")); } }
      catch(x){ paint(String(x.message) === "refus" ? t("Tu n'as pas autorisé les notifications.") : t("Impossible pour le moment. Vérifie ta connexion.")); } };
    box.querySelectorAll("[data-tp]").forEach(c=>{ c.onclick = e=>e.stopPropagation(); c.onchange = async ()=>{
      const next = [...box.querySelectorAll("[data-tp]")].filter(x=>x.checked).map(x=>x.dataset.tp); ls.set("skf-push-topics", JSON.stringify(next));
      const s = await current(); if(s){ try{ await save(s); }catch(e){} } }; });
  }
  const pop = document.getElementById("setPop");
  if(pop) new MutationObserver(row).observe(pop, {childList:true});
  row();
})();

